    /**
     * Logs a message
     * @param message 
     */
    @Override
    public void log(String message)
    {
        javax.swing.SwingUtilities.invokeLater(() ->
        {
            this.debugArea.insert(message + "\n", 0);
            this.debugArea.setCaretPosition(0);

            // Capped, because this document otherwise grows for the life of the session and every
            // insert is at position 0 - which shifts everything already in it.  The per-message cost
            // therefore rose with session age, on the thread that paints the whole UI, and with debug
            // logging on a long session slowed the application down for a reason nothing pointed at.
            // Trimming the tail keeps the newest-first presentation the front insert exists for.
            int length = this.debugArea.getDocument().getLength();

            if (length > DEBUG_LOG_MAX_CHARS)
            {
                try
                {
                    this.debugArea.getDocument().remove(DEBUG_LOG_MAX_CHARS, length - DEBUG_LOG_MAX_CHARS);
                }
                catch (javax.swing.text.BadLocationException e)
                {
                    // Only reachable if the offsets disagree with the document, which cannot happen
                    // when both come from the document itself one statement earlier
                }
            }
        });
    }             
    
    public int getKeyboardOffset()
    {
        return (this.keyboardNumber - 1) * TrainControlUI.KEYBOARD_KEYS;
    }
    
    private void switchLocMapping(int locPageNum)
    {
        if (locPageNum <= this.numLocMappings && locPageNum >= 1)
        {
            this.locMappingNumber = locPageNum;
        }
         
        if (this.numLocMappings > 1)
        {
            if (this.locMappingNumber == 1)
            {
                this.PrevLocMapping.setEnabled(false);
            }
            else
            {
                this.PrevLocMapping.setEnabled(true);
            }

            if (this.locMappingNumber == this.numLocMappings)
            {
                this.NextLocMapping.setEnabled(false);
            }
            else
            {
                this.NextLocMapping.setEnabled(true);
            }
            
            this.LocMappingNumberLabel.setText(this.getPageName(this.locMappingNumber, false, true));
            
            this.locKeyTabs.setSelectedIndex(this.locMappingNumber - 1);
            this.locKeyTabs.setTitleAt(this.locMappingNumber - 1, getLocMappingPageTabTitle(this.locMappingNumber));
            
            // Display current mapping number in the tab label
            this.KeyboardTab.setToolTipTextAt(
                0,
                I18n.f("loc.ui.tooltip.locomotiveControlPage", this.locMappingNumber)
            );

            // The page number as a badge in the corner, not a digit across the middle.
            this.KeyboardTab.setIconAt(0, new javax.swing.ImageIcon(withPageBadge(
                ImageUtil.convertIconToBufferedImage((ImageIcon) TAB_ICON_CONTROL),
                this.locMappingNumber)));
       }
       else 
       {
            this.NextLocMapping.setVisible(false);
            this.PrevLocMapping.setVisible(false);
            this.LocMappingNumberLabel.setText("");
       } 
        
       repaintMappings();        
    }
    
    /**
     * Sets the name of the currently active mapping page
     * @param name 
     */
    private void setPageName(String name)
    {
        if (name == null || "".equals(name.trim()))
        {
            this.pageNames.remove(this.locMappingNumber);
        }
        else
        {            
            this.pageNames.put(this.locMappingNumber, name.trim());
        }
        
        this.LocMappingNumberLabel.setText(this.getPageName(this.locMappingNumber, false, true));
        this.repaintLoc(true, null);
    }
    
    /**
     * Optional 3rd argument...
     * @param mappingNumber
     * @param raw
     * @return 
     */
    private String getPageName(int mappingNumber, boolean raw)
    {
        return getPageName(mappingNumber, raw, false);
    }
    
    /**
     * Returns the currently shown page number
     * @return 
     */
    public int getLocMappingNumber()
    {
        return locMappingNumber;
    }
    
    /**
     * Gets the name of the specified mapping page
     * @param mappingNumber
     * @param raw - do we exclude the page number
     * @return 
     */
    private String getPageName(int mappingNumber, boolean raw, boolean html)
    {
        if (this.pageNames.containsKey(mappingNumber))
        {
            String name = this.pageNames.get(mappingNumber);

            if (!raw)
            {                
                if (html)
                {
                    if (name.length() > TrainControlUI.MAX_PAGE_NAME_LENGTH)
                    {
                        name = name.substring(0, MAX_PAGE_NAME_LENGTH);
                    }

                    name = I18n.f(
                        "page.ui.htmlPageName",
                        name,
                        mappingNumber
                    );
                }
                else
                {
                    if (name.length() > TrainControlUI.MAX_PAGE_NAME_LENGTH_TOP)
                    {
                        name = name.substring(0, MAX_PAGE_NAME_LENGTH_TOP) + "...";
                    }

                    name = I18n.f(
                        "page.ui.plainPageName",
                        mappingNumber,
                        name
                    );
                }
            }
            
            return name;   
        }
        else
        {
            if (raw)
            {
                return "";
            }
            else
            {
                return I18n.f("page.ui.pageNo", mappingNumber);
            }
        }
    }
    
    /**
     * Prompts the user for the name of the current page
     */
    public void renameCurrentPage()
    {
        String input = JOptionPane.showInputDialog(
            this,
            I18n.f("page.ui.promptEnterPageName", this.locMappingNumber),
            this.getPageName(this.locMappingNumber, true)
        );

        if (input != null)
        {
            input = input.trim();

            // THE PAGE NAMES, not the two sentinels that share the map (SVN-C13).
            //
            // `pageNames` also holds the active page number and the active button's key code, under
            // keys -1 and -2, and they are written as strings.  `containsValue` saw them - so after any
            // start from a saved state, naming a page the digits of the last-saved active page ("3"),
            // or the key code of the active button ("81" for Q), was refused as a duplicate of a page
            // that does not exist.
            if (namesOfPages().contains(input)
                && !input.equals(this.getPageName(this.locMappingNumber, true).trim()))
            {
                JOptionPane.showMessageDialog(
                    this,
                    I18n.t("page.ui.errorDuplicatePageName")
                );
            }
            else
            {
                this.setPageName(input);
            }
        }
    }
    
    private void switchKeyboard(int keyboardNum)
    {
        javax.swing.SwingUtilities.invokeLater(() ->
        {
            int tarKeyboard = keyboardNum;
            
            // Ensure bounds
            if (keyboardNum < 1)
            {
                tarKeyboard = 1;
            }
            
            if (keyboardNum > TrainControlUI.NUM_KEYBOARDS)
            {
                tarKeyboard = TrainControlUI.NUM_KEYBOARDS;
            }
            
            if (tarKeyboard <= TrainControlUI.NUM_KEYBOARDS && tarKeyboard >= 1)
            {
                this.keyboardNumber = tarKeyboard;
            }

            if (this.keyboardNumber == 1)
            {
                this.PrevKeyboard.setEnabled(false);
            }
            else
            {
                this.PrevKeyboard.setEnabled(true);
            }

            if (this.keyboardNumber == TrainControlUI.NUM_KEYBOARDS)
            {
                this.NextKeyboard.setEnabled(false);
            }
            else
            {
                this.NextKeyboard.setEnabled(true);
            }

            this.KeyboardNumberLabel.setText(
                I18n.f("keyboard.ui.labelKeyboardNumber", this.keyboardNumber)
            );

            Integer offset = this.getKeyboardOffset();

            for (Integer i = 1; i <= TrainControlUI.KEYBOARD_KEYS; i++)
            {
                this.switchMapping.get(i).setText((Integer.valueOf(i + offset)).toString());

                // Set the font size dynamically 
                int fontSize = i + offset > 960 ? 11 : 14;
                this.switchMapping.get(i).setFont(new java.awt.Font("Segoe UI", java.awt.Font.BOLD, fontSize));
            }

            repaintSwitches();
        });
    }
    
    /**
     * Fetches and scales a resource icon
     * @param size
     * @param file
     * @return 
     */
    private static ImageIcon getTabIcon(int size, String file)
    {
        ImageIcon icon = new ImageIcon(TrainControlUI.class.getResource("resources/" + file)); 
        Image scaledImage = icon.getImage().getScaledInstance(-1, size, Image.SCALE_SMOOTH); 
        return new ImageIcon(scaledImage);
    }
    
    public void setViewListener(ViewListener listener, CountDownLatch latch) throws IOException
    {
        // Set the model reference
        this.model = listener;
                 
        List<Map<Integer, String>> saveStates = this.restoreState();
        boolean locWasLoaded = false;
        
        // A saved state with more pages than the preference says GROWS the preference.
        //
        // The count used to be fixed, so a state could never hold more than it - now it can, and the
        // alternative to growing is silently dropping every mapping past the tenth.  The last entry
        // is the page names rather than a page, hence the -1.
        //
        // NOT SUBJECT TO MAX_LOC_MAPPINGS, and this is the half of that cap worth protecting.  Adding
        // a page stops at fifty (2026-08-27); loading pages that already exist does not stop at all,
        // because the only way to honour a ceiling here is to drop what is above it.  The two rules
        // read as an oversight and are not one - see `addLocMappingPage`.
        boolean grew = false;

        while (saveStates.size() - 1 > this.numLocMappings)
        {
            this.numLocMappings++;
            this.locMapping.add(new HashMap<>());

            // The TAB as well as the page.  The tab strip is built in the constructor, from the count
            // as the preference had it - so growing the count here and not the strip left the extra
            // pages with nothing to click, and switchLocMapping, which selects a tab by number, threw
            // out of the tab pane instead of saying anything.
            this.locKeyTabs.add(getLocMappingPageTabTitle(this.numLocMappings), new JPanel());

            grew = true;
        }

        if (grew)
        {
            // And written down, so the next start does not have to work it out again - and does not
            // go back to disagreeing with the saved state.
            prefs.putInt(LOC_MAPPING_PAGES_PREF, this.numLocMappings);

            adjustTabbedPaneHeight(locKeyTabs);
        }

        // size() - 1 because the last entry is the page names rather than a page.  It did no harm
        // read as one - its keys are page numbers and two sentinels, and a page is keyed by VK_A..VK_Z,
        // so every lookup missed - but a loop that reads the wrong thing and gets away with it is one
        // rename away from not getting away with it.
        for (int j = 0; j < saveStates.size() - 1 && j < this.numLocMappings; j++)
        {
            Map<Integer, String> saveState = saveStates.get(j);
     
            for(Integer i : saveState.keySet())
            {
                JButton b = this.buttonMapping.get(i);

                Locomotive l = this.model.getLocByName(saveState.get(i));

                if (l != null && b != null)
                {
                    locWasLoaded = true;
                    
                    // this.model.log("Loading mapping for page " + Integer.toString(j + 1) + ", " + l.getName());
                    this.locMapping.get(j).put(b, l);
                }
            }
        }
        
        boolean savedLocKey = false;
        // Restore page names, active button, and page, which are stored at the end
        // The last entry, whenever there IS one.
        //
        // saveState always appends the page names after the pages, so the list is always one longer
        // than the page count - but this was gated on the count in the PREFERENCE, which only matches
        // when the two agree.  A preference larger than the file (a page added, then an unclean exit;
        // or, before the folder hash above, a page added in another working directory) skipped the
        // page names, the active page and the active button - and the exit then serialised the empty
        // map over them.  The button mappings survived, so it read as "my page names vanished".
        if (!saveStates.isEmpty())
        {
            this.pageNames = saveStates.get(saveStates.size() - 1);
            
            try
            {
                if (this.pageNames.containsKey(SAVE_KEY_ACTIVE_MAPPING_NUMBER))
                {
                    this.switchLocMapping(Integer.parseInt(this.pageNames.get(SAVE_KEY_ACTIVE_MAPPING_NUMBER)));
                } 

                if (this.pageNames.containsKey(TrainControlUI.SAVE_KEY_ACTIVE_BUTTON) && 
                        this.buttonMapping.containsKey(Integer.valueOf(this.pageNames.get(SAVE_KEY_ACTIVE_BUTTON))))
                {
                    this.displayCurrentButtonLoc(this.buttonMapping.get(Integer.valueOf(this.pageNames.get(SAVE_KEY_ACTIVE_BUTTON))));
                    savedLocKey = true;
                } 
            }
            catch (Exception e)
            {
                this.model.logf(
                    "ui.errorParseMappingOrButton"
                );
            }
        }
             
        // Hide initially
        locCommandPanels.remove(this.locCommandTab);
        locCommandPanels.remove(this.timetablePanel);
        locCommandPanels.remove(this.autoSettingsPanel);
        
        // Add the first locomotive to the mapping if nothing was loaded
        if (!this.model.getLocList().isEmpty() && !locWasLoaded)
        {
            this.currentLocMapping().put(
                QButton, 
                this.model.getLocByName(this.model.getLocList().get(0))
            );
        }
        
        // Display the locomotive
        if (!savedLocKey)
        {
            displayCurrentButtonLoc(QButton);
        }
        
        // Display loc mapping page
        this.switchLocMapping(this.locMappingNumber);
        
        // Generate list of locomotives
        selector = new LocomotiveSelector(this.model, this);
        selector.init();
        
        adder = new AddLocomotive(this.model, this);
        adder.setLocationRelativeTo(this);
        selector.setLocationRelativeTo(this);
        
        // Load autonomy data.  Current versions store autonomy.json as raw JSON; older versions stored it as
        // an ObjectOutputStream-serialized String, so detect and fall back to that for files written by them.
        try
        {
            byte[] bytes = Files.readAllBytes(Paths.get(TrainControlUI.AUTONOMY_FILE_NAME));
            this.autonomyJSON.setText(decodeAutonomyJson(bytes));
        }
        catch (IOException | ClassNotFoundException e)
        {
            this.model.logf(
                "autolayout.errorReadAutonomyState",
                TrainControlUI.AUTONOMY_FILE_NAME
            );
        }
                        
        // Add list of routes to tab
        refreshRouteList();
                
        // Add list of layouts to tab
        this.LayoutList.setModel(new DefaultComboBoxModel(listener.getLayoutList().toArray()));
                
        // Display keyboard
        this.switchKeyboard(this.keyboardNumber);
        
         // Hide CS3 app button on non-CS3 controllers
        if (!this.model.isCS3())
        {
            this.openCS3AppMenuItem.setEnabled(false);
        }
                
        HandScrollListener scrollListener = new HandScrollListener(InnerLayoutPanel);
        LayoutArea.getViewport().addMouseMotionListener(scrollListener);
        LayoutArea.getViewport().addMouseListener(scrollListener);
             
        this.latencyLabel.setText(
            I18n.t("ui.labelNotConnectedToCentralStation")
        );

        // Start with true to ensure keyboard events register properly
        // If we don't do this, initializing the UI from the EDT will cause issues
        setAlwaysOnTop(true);
        
        // Render layout now that the UI is visible
        repaintLayout();
        
        // Asked ONCE, of the stored answer (OB-127).
        //
        // This is the offer to create a track diagram. It read the model directly, so it answered for
        // the instant it happened to run rather than for the state the rest of the window was showing.
        updateLayoutLoaded();

        if (!isLayoutLoaded())
        {
            // ASKED ONLY IF THERE IS SOMEBODY TO ASK (Adam, 2026-08-28).
            //
            // "if the app is started FOR THE FIRST TIME (there exist no DB files yet) and there is no
            // layout, create one instead of prompting the user."  Nobody opening this for the first
            // time has a view on whether it should make a track diagram - they have not seen one, and
            // the other answer leaves them an application with nothing in it.
            //
            // Every later start still asks, because by then "no layout" means one was there and is
            // not, and that is worth a question.
            createAndApplyEmptyLayout(TrainControlUI.DEMO_LAYOUT_OUTPUT_PATH, !isFirstLaunch());
        }
        
        // Populate statistics tab
        this.stats = new LocomotiveStats(this);
        this.KeyboardTab.add(this.stats, "Stats", this.KeyboardTab.getComponentCount() - 1);
        
        // Routes before signals and switches (Adam, 2026-08-27: "swap the position of the route tab
        // with the keyboard tab").
        //
        // Moved HERE rather than in the designer.  The tab strip is built in the generated block, and
        // that block is not ours to edit - so the order it produces is taken as given and corrected
        // once, in one place, before anything below addresses a tab by number.
        //
        // Everything that follows is written against the order this leaves behind:
        //
        //     0 control   1 diagram   2 autonomy   3 ROUTES   4 KEYBOARD   5 stats   6 log
        //
        // The two handlers that ask which tab is showing are unaffected either way - one tests for the
        // diagram at 1 and one for autonomy at 2, and the statistics refresh counts back from the end
        // rather than naming an index.
        // Found by IDENTITY rather than counted to (C8).
        //
        // `getComponentAt(4)` was right only because the designer happens to add the tabs in a
        // particular order and the statistics tab is inserted above this: a reorder in the form editor
        // would move some other panel to 3, every assertion in the guard test would still pass, and
        // the sidebar would be quietly wrong. Asking for the RoutePanel cannot be wrong about which
        // panel it means.
        int routesAt = this.KeyboardTab.indexOfComponent(this.RoutePanel);

        // The icons below are numbered for the order this produces, so skipping the move quietly would
        // leave routes wearing the signals icon and tooltip and vice versa - every icon on the wrong
        // tab, nothing thrown, nothing logged (validator).  The old hard-coded version would at least
        // have thrown.  If the panel is not in the strip at all there is nothing this method can do
        // that is right, and saying so beats carrying on.
        if (routesAt < 0)
        {
            throw new IllegalStateException("the routes panel is not in the sidebar, so the tab order "
                + "and the icons below cannot be made to agree");
        }

        java.awt.Component routes = this.KeyboardTab.getComponentAt(routesAt);

        this.KeyboardTab.remove(routesAt);
        this.KeyboardTab.insertTab("Rout", null, routes, null, 3);

        // Set pane icons   
        // this.KeyboardTab.setIconAt(0, TAB_ICON_CONTROL);
        // this.KeyboardTab.setToolTipTextAt(0, "Locomotive Control");
        this.KeyboardTab.setTitleAt(0, "");
        this.KeyboardTab.setIconAt(1, TAB_ICON_LAYOUT);
        this.KeyboardTab.setToolTipTextAt(
            1,
            I18n.t("ui.tooltip.Layout")
        );
        this.KeyboardTab.setTitleAt(1, "");
        this.KeyboardTab.setIconAt(3, TAB_ICON_ROUTES);
        this.KeyboardTab.setToolTipTextAt(
            3,
            I18n.t("ui.tooltip.Routes")
        );
        this.KeyboardTab.setTitleAt(3, "");
        this.KeyboardTab.setIconAt(4, TAB_ICON_KEYBOARD);
        this.KeyboardTab.setToolTipTextAt(
            4,
            I18n.t("ui.tooltip.SignalsAndSwitches")
        );
        this.KeyboardTab.setTitleAt(4, "");
        this.KeyboardTab.setIconAt(2, TAB_ICON_AUTONOMY);
        this.KeyboardTab.setToolTipTextAt(
            2,
            I18n.t("ui.tooltip.FullAutomation")
        );
        this.KeyboardTab.setTitleAt(2, "");
        this.KeyboardTab.setIconAt(5, TAB_ICON_STATS);
        this.KeyboardTab.setToolTipTextAt(
            5,
            I18n.t("ui.tooltip.Statistics")
        );
        this.KeyboardTab.setTitleAt(5, "");
        this.KeyboardTab.setIconAt(6, TAB_ICON_LOG);
        this.KeyboardTab.setToolTipTextAt(
            6,
            I18n.t("ui.tooltip.Log")
        );
        this.KeyboardTab.setTitleAt(6, "");
        
        // FR-032's hover crop mark, which needs locIcon to exist and so cannot be in the designer.
        buildCropOverlay();

        // Remove the default action for the up/down arrow keys
        InputMap inputMap = this.KeyboardTab.getInputMap(JComponent.WHEN_FOCUSED);
        inputMap.put(KeyStroke.getKeyStroke(KeyEvent.VK_DOWN, 0), "none");
        inputMap.put(KeyStroke.getKeyStroke(KeyEvent.VK_UP, 0), "none");
        
        // Monitor for network activity and show a warning if CS2/3 seems unresponsive
        new Thread(() ->
        {            
            try
            {
                Thread.sleep(CAN_MONITOR_DELAY * 1000);
            } catch (InterruptedException ex)
            {
                Thread.currentThread().interrupt();
            }
            
            if (this.model.getNumMessagesProcessed() == 0
                && this.model.getNetworkCommState()
            )
            {
                String message = I18n.f(
                    "ui.warningNoCanMessages",
                    CAN_MONITOR_DELAY
                );

                this.model.log(message);

                javax.swing.SwingUtilities.invokeLater(() ->
                {
                    JOptionPane.showMessageDialog(
                        this,
                        I18n.f("ui.warningNoCanMessagesDialog", message)
                    );
                });
            }
        }).start();
        
        // Check for updates
        this.downloadUpdateMenuItem.setVisible(false);
        
        if (this.model != null && this.checkForUpdates.isSelected())
        {
            new Thread(() ->
            { 
                try
                {
                    JSONObject updateInfo = Util.getLatestReleaseInfo(GITHUB_REPO);
                    LATEST_VERSION = Util.parseReleaseVersion(updateInfo);
                    LATEST_DOWNLOAD_URL = Util.parseDownloadURL(updateInfo);
                    
                    if (Util.parseReleaseURL(updateInfo) != null)
                    {
                        UPDATE_URL = Util.parseReleaseURL(updateInfo);
                    }
                    
                    this.model.logf(
                        "ui.infoLatestAvailableVersion",
                        LATEST_VERSION
                    );

                    if (Conversion.compareVersions(LATEST_VERSION, RAW_VERSION) > 0)
                    {
                        javax.swing.SwingUtilities.invokeLater(() ->
                        {
                            this.downloadUpdateMenuItem.setVisible(true);
                            this.viewReleasesMenuItem.setText("v" + LATEST_VERSION + " Update Info");
                            this.helpMenu.setText(this.helpMenu.getText() + "*");
                        });
                    }
                }
                catch (Exception e)
                {
                    this.model.logf(
                        "ui.errorFetchLatestUpdateInfo"
                    );

                    if (this.model.isDebug())
                    {
                        this.model.log(e);
                    }
                }
            }).start();   
        }
                
        // Monitor latency
        if (this.model != null && model.getNetworkCommState() && PING_INTERVAL > 0)
        {            
            model.sendPing(true);
            
            // A DAEMON timer.  The handle is discarded - nothing ever cancels this - so as an
            // ordinary Timer its thread kept the JVM alive after the window closed, which
            // System.exit(0) was quietly covering for.
            (new Timer(true)).scheduleAtFixedRate(new TimerTask()
            {
                @Override
                public void run()
                {
                    try
                    {
                        if (model.getTimeSinceLastPing() > 0 && model.getTimeSinceLastPing() > PING_INTERVAL)
                        {
                            javax.swing.SwingUtilities.invokeLater(() ->
                            {
                                latencyLabel.setText(
                                    I18n.t("ui.labelLostNetworkConnection")
                                );
                                latencyLabel.setForeground(Color.red);
                            });
                            
                            checkAutoLayoutLatency(PING_INTERVAL);
                        }
                        
                        model.sendPing(false);
                    }
                    catch (Exception e)
                    {
                        model.logf(
                            "ui.errorSendingPing",
                            e.getMessage()
                        );
                        
                        model.log(e);
                    }
                }
            }, 0, PING_INTERVAL);
        }
        
        // Autonomy managed on the diagram replaces the JSON window wherever this layout can hold a
        // setup; where it cannot (no local copy), the JSON window stays and nothing below changes.
        this.mountAutonomyControls();

        // Settled unconditionally, before anything is loaded.  This used to be decided only inside
        // the auto-load branch below, which is the one case that does NOT need it: with auto-load off,
        // or with nothing to resume, the window opened on an Auto tab that was enabled and empty.
        refreshAutonomyTabState();

        // And whether this layout has a setup nobody has loaded, which is the state the diagram itself
        // has to say something about - it is where the user is looking, and it is where the stations
        // they are wondering about would be.
        javax.swing.SwingUtilities.invokeLater(() -> refreshAutonomyPrompt());

        // Load autonomy if requested
        if (this.AutoLoadAutonomyMenuItem.isSelected())
        {
            javax.swing.SwingUtilities.invokeLater(() ->
            {
                // The active configuration resumes from the diagram when there is one; the JSON path
                // remains the fallback for layouts that have never been set up the new way.
                org.traincontrol.automationui.AutonomySession session = getAutonomySession();

                if (session != null && this.getAutonomyViewerPanel() != null
                    && session.getStore().getActiveConfiguration() != null)
                {
                    this.getAutonomyViewerPanel().loadActive();
                }
                else
                {
                    this.validateButtonActionPerformed(new CustomActionEvent(this, ActionEvent.ACTION_PERFORMED, "", ""));
                }

                refreshAutonomyTabState();
                refreshAutonomyPrompt();
            });
        }
                
        // Release the latch
        if (latch != null) latch.countDown();
        
        // Show window - this is now called externally once this call returns        
    }
    
    /**
     * Renders the UI once everything is initialized - to be called externally
     */
    public void display()
    {     
        // THE NOTICE COMES OFF FIRST (OB-170, 2026-09-03).
        //
        // The window has been on screen since before the connect, showing a spinner and a line of
        // words, and this is where the application it was standing in for takes its place.  Nothing
        // below has to know: by the time it runs, this is an ordinary window being made ready.
        connectingFinished();

        // Remember window location.  Because isResizable is already false, this will not restore the size
        this.loadWindowBounds();
        
        // Ensure the preference is properly set across the layouts
        this.ensureShowLayoutPreference(); 
        
        // Ensure the locomotive pane is updated
        this.repaintLoc(true, null);
        
        // SHOWN WHILE STILL TOPMOST, and it stays that way until the raise below hands the flag back
        // (OB-170, seventh pass).
        //
        // `setViewListener` sets always-on-top true before this, and says why: "start with true to
        // ensure keyboard events register properly".  That is not a preference, it is the mechanism -
        // a topmost window is the one case Windows lets a process raise without already owning the
        // foreground.
        //
        // The operator's setting used to be restored on the very next line, and showing a window is
        // asynchronous: the style was gone before the window manager had acted on the show.  In 2.8.1
        // that did no harm, because there the main window is the FIRST window the process shows and is
        // activated by the one-time right a process gets when the user starts it.  3.0.0 shows a splash
        // first, which spends that right - so the frame has nothing but the trick, and the trick was
        // being undone microseconds after it was played.
        //
        // `takeTheKeyboard` at the foot of this method owns the restore now.  It already holds the flag
        // for four hundred milliseconds, which is the window the show needs.
        setVisible(true);

        pack();
        displayMenuBar();
        
        // Dynamically set this to prevent bug where the UI shrinks after computer sleeps
        setMinimumSize(new java.awt.Dimension(this.getSize().width, this.getSize().height));
        setPreferredSize(new java.awt.Dimension(this.getSize().width, this.getSize().height));
        
        if (this.powerOnStartup.isSelected())
        {
            go();
        }
        else if (this.powerOffStartup.isSelected())
        {
            stop();
        }
        
        // TrackDiagramEditor Layout editing only supported on windows
        if (!this.isWindows())// || !model.isDebug())
        {
            this.openLegacyTrackDiagramEditor.setVisible(false);
        }
        
        // Debug mode indicator
        if (this.model.isDebug())
        {
            setTitle(this.getTitle() + " [" + I18n.t("ui.debug") + "]");
        }
                
        restoreLayoutTitles();

        // On every path, not only the one with a local layout folder (RG3-C3).
        removeLegacyEditorItem();

        takeTheKeyboard();
    }

    /**
     * What the window was holding before the connecting notice went over it, or null when it is not
     * showing one.
     */
    private java.awt.Container contentBehindTheNotice;

    /**
     * Puts this window on screen with a "connecting" notice on it, before there is anything to show
     * (OB-170, 2026-09-03).
     *
     * **This exists because a second window cannot be used for it.**  Start-up used to show a splash -
     * a small always-on-top window of its own - and showing one spends the process's single chance at
     * putting a window in the foreground.  The main window then arrived into somebody else's
     * foreground, and nothing it could do got the keyboard back, because a process that is not in the
     * foreground is not allowed to put itself there.
     *
     * Measured three ways before it was believed: with the splash suppressed the start-up keyboard
     * works; with it shown and closed before the window it does not; with it shown and closed after the
     * window it does not.  Adam ran all three.
     *
     * So the process shows exactly one window, which is what 2.8.1 does and why 2.8.1's keyboard works.
     *
     * **The content pane is swapped rather than covered.**  A glass pane would leave the real
     * components painting underneath it, and they read a model that does not exist yet - there is no
     * `ViewListener` until the connect is over.  Swapping means nothing model-dependent is asked to
     * draw itself before there is a model.
     *
     * @param message what is happening, in words
     */
    public void showConnecting(String message)
    {
        if (contentBehindTheNotice != null) return;

        contentBehindTheNotice = getContentPane();

        setContentPane(StartupSplash.panel(message));

        // AND THE MENUS WITH IT.  Adam: "just gray out the menu bar before it loads, too."  The bar is
        // part of the window rather than of its content, so swapping the content leaves every menu
        // sitting there looking ready - and none of them can do anything: they command a model that
        // does not exist until the connect is over.
        greyTheMenus();

        // Where it is going to live, so it does not appear in one place and jump to another.
        loadWindowBounds();

        setVisible(true);
    }

    /**
     * Gives the window its own content back, once there is something to show.
     *
     * Safe to call when no notice was ever shown - the headless and no-window start-ups never call
     * `showConnecting`, and `display()` calls this unconditionally.
     */
    public void connectingFinished()
    {
        if (contentBehindTheNotice == null) return;

        setContentPane(contentBehindTheNotice);

        contentBehindTheNotice = null;

        ungreyTheMenus();

        revalidate();
        repaint();
    }

    /**
     * The menus this window greyed out while it was connecting, so that only those go back.
     */
    private final java.util.List<javax.swing.JMenu> menusGreyedByTheNotice = new java.util.ArrayList<>();

    /**
     * Greys out the menu bar for as long as the connecting notice is up.
     *
     * **Each menu, not the bar.**  `JMenuBar.setEnabled(false)` leaves its menus drawn in their
     * ordinary colour and still opening; the greying an operator recognises is on the JMenu itself.
     *
     * **What was already disabled stays disabled.**  Several items are switched off by state - no
     * layout, no local folder, no update to download - and re-enabling everything afterwards would
     * turn those on, which is a worse fault than the one being fixed.  Hence the list: only what this
     * turned off is turned back on.
     *
     * Separate from `showConnecting` so it can be tested without putting a window on somebody's
     * screen, which is a thing this suite is not allowed to do.
     */
    private void greyTheMenus()
    {
        javax.swing.JMenuBar bar = getJMenuBar();

        if (bar == null) return;

        for (int i = 0; i < bar.getMenuCount(); i++)
        {
            javax.swing.JMenu menu = bar.getMenu(i);

            // getMenu returns null for anything in the bar that is not a JMenu - a glue or a strut.
            if (menu == null || !menu.isEnabled()) continue;

            menu.setEnabled(false);

            menusGreyedByTheNotice.add(menu);
        }
    }

    /**
     * Gives back exactly the menus `greyTheMenus` took, and nothing else.
     */
    private void ungreyTheMenus()
    {
        for (javax.swing.JMenu menu : menusGreyedByTheNotice)
        {
            menu.setEnabled(true);
        }

        menusGreyedByTheNotice.clear();
    }

    /**
     * Takes the window off the screen when the start-up it was reporting has failed.
     *
     * The old splash was closed on every path out of `init` for the same reason, and its comment is
     * still the right one: something left standing over a failure the operator cannot see through is
     * the "looks hung mid-connect" symptom the notice exists to remove.  A window still saying
     * "connecting" while an error dialog stands in front of it is that, exactly.
     */
    public void connectingFailed()
    {
        // ON THE EVENT THREAD, whoever calls it (REL-C1).
        //
        // The three callers are failure paths in `MarklinControlStation.init`, all on the caller's own
        // thread, and this method swaps the content pane, revalidates, repaints and hides a realized
        // visible frame.  `StartupSplash.close()`, which these replaced, marshalled itself - "if
        // isEventDispatchThread run it, else invokeLater" - and the rewrite dropped that.  Swing does
        // not throw for it; what it gives you is a paint race on a window being torn down, at the
        // moment an error dialog is about to go up.
        //
        // Here rather than at the three call sites, so a fourth cannot forget.
        if (!javax.swing.SwingUtilities.isEventDispatchThread())
        {
            javax.swing.SwingUtilities.invokeLater(() -> connectingFailed());

            return;
        }

        connectingFinished();

        setVisible(false);
    }

    /**
     * Puts the keyboard where the operator expects it once the window is up (OB-168).
     *
     * Adam: **"ensure the UI is focused once the window is rendered so that keystrokes are registered
     * on the main traincontrol window (locomotive letters, etc.)"**
     *
     * **Not the frame.**  It is set non-focusable when the form is built, so `requestFocus()` on it
     * does nothing whatsoever - which is why `display()` looked as though it had never needed this.
     * The letter keys are read by KeyListeners on the tabbed pane and on the locomotive panel, and one
     * of those has to be holding the focus before a keystroke reaches either of them.  The tabbed pane
     * is the one that can take it: a JPanel is not focusable unless somebody says so, and nobody does.
     *
     * Posted rather than called, because focus asked for during the same event that made the window
     * visible is asked for before the window manager has finished putting it on the screen, and on
     * Windows that request is simply dropped.  The editor's own showOpenEditor() does the same pair -
     * toFront then focus - for the same reason.
     */
    private void takeTheKeyboard()
    {
        // THE WINDOW FIRST, AND THEN WHAT IS IN IT - but not in the same breath (OB-170, fifth pass).
        //
        // `focusTheKeyboard()` used to be called here, one line after the raise.  The raise is not
        // finished when it returns: the always-on-top flag it sets is handed back four hundred
        // milliseconds later, and changing that flag is a native window-style change that resets which
        // component holds the focus.  So the keyboard was given to the tabbed pane and then taken away
        // again by our own restore.
        //
        // Adam's evidence for this is the message that did NOT appear: the window was active, so the
        // front was never the problem by then.
        javax.swing.SwingUtilities.invokeLater(() -> comeToTheForeground());

        // AND AGAIN WHENEVER IT GAINS FOCUS WITH NOTHING INSIDE IT FOCUSED (OB-170).
        //
        // Asking once was the fix for OB-168 and it was not enough: Adam reported the same symptom
        // against a build carrying it.  `requestFocusInWindow` returns false and does nothing while
        // the window is not the FOCUSED window, and `toFront()` on Windows does not reliably make a
        // starting process's window one - so the request was made at a moment it could not be granted
        // and then never made again.
        //
        // He asked whether the startup splash is involved.  Not through ordering - `StartupSplash`
        // closes synchronously on the event thread, before `display()` is posted - but it is the same
        // shape: an always-on-top window that held the focus and then vanished leaves the focus
        // wherever the window manager likes.  This covers that, an update prompt, any dialog dismissed
        // during start-up, and alt-tabbing back afterwards.
        addWindowFocusListener(new java.awt.event.WindowAdapter()
        {
            @Override
            public void windowGainedFocus(java.awt.event.WindowEvent e)
            {
                // POSTED, not called - measured, not reasoned.
                //
                // AWT's own handling of this event restores the focus to the window's most recent
                // focus owner, and a request made from inside a listener on the event is made before
                // that restoration and then undone by it.  The test for this came back holding a
                // JLabel until the request was moved behind it.
                //
                // Which is the sentence above arriving a second time, at the next event along: focus
                // asked for during the event that grants it is asked for too early.
                javax.swing.SwingUtilities.invokeLater(() -> focusTheKeyboard());
            }
        });
    }

    /**
     * Makes this the active window, which on Windows is not what `toFront()` does (OB-170, third pass).
     *
     * **The two fixes before this one were aimed a level too deep.**  They arranged which COMPONENT
     * holds the keyboard once the window has it; Adam's answer both times was that the window does not
     * have it - *"the frame is not active and keystrokes do not go to it.  the previous active
     * application window retains focus"*, and *"the entire window is still not in focus, rather the
     * parent app like the python or netbeans remains"*.  Nothing about focus WITHIN a window helps
     * with that.
     *
     * Windows refuses a foreground change requested by a process that is not already in the
     * foreground.  An application started from NetBeans, a terminal or a script is never that process,
     * so `toFront()` raises the window behind whatever is in front and flashes the taskbar button
     * instead.  The always-on-top toggle below is the way out, and it is less a trick than the one
     * case the rule leaves open: a topmost window is allowed to raise itself, because it is already
     * above everything.
     *
     * Called once, from start-up.  Doing it on every activation would let the application pull itself
     * in front of whatever the operator had just switched to - the fault this cures, pointed the other
     * way.
     */
    private void comeToTheForeground()
    {
        // Un-minimised first: a window in the iconified state cannot be activated at all.  The
        // ICONIFIED bit is cleared rather than the state replaced, because the same field carries the
        // maximised bits and replacing it would un-maximise a window somebody had maximised.
        if ((getExtendedState() & java.awt.Frame.ICONIFIED) != 0)
        {
            setExtendedState(getExtendedState() & ~java.awt.Frame.ICONIFIED);
        }

        // THE OPERATOR'S SETTING, not the window's current one (OB-170, seventh pass).
        //
        // The window arrives here still topmost on purpose - `display()` no longer takes the flag off,
        // because doing so before the show had been acted on is what stopped the raise working.  So
        // asking `isAlwaysOnTop()` would read our own mechanism back and leave the application above
        // everything else for ever.
        raiseOnce(prefs.getBoolean(ONTOP_SETTING_PREF, ONTOP_SETTING_DEFAULT), 1);
    }

    /**
     * How long the window manager is given to act on a raise before the topmost flag is handed back.
     *
     * **This number is the fix.**  `setAlwaysOnTop(true)` changes the window's native style and
     * `toFront()` POSTS a raise; handing the flag back in the same breath - which is what a `finally`
     * does - meant the raise was processed against an ordinary window and refused by the same
     * foreground rule the flag exists to get past.
     */
    private static final int FOREGROUND_SETTLE_MS = 400;

    /**
     * One attempt at the front, with the topmost flag handed back afterwards rather than immediately.
     *
     * Tried twice in all.  The first attempt happens while the application is still starting, which is
     * the moment the window manager is least likely to co-operate; the second is a quarter of a second
     * later, when whatever else was claiming the screen has usually finished.  Two rather than a loop,
     * because an application that keeps pulling itself in front is a worse fault than one that does
     * not come forward, and the operator may have deliberately switched away by then.
     *
     * @param wasOnTop the always-on-top setting to restore, which is the operator's and not ours
     * @param attempt 1 for the first go, 2 for the retry
     */
    private void raiseOnce(final boolean wasOnTop, final int attempt)
    {
        setAlwaysOnTop(true);

        toFront();

        requestFocus();

        javax.swing.Timer settle = new javax.swing.Timer(FOREGROUND_SETTLE_MS, event ->
        {
            // The operator's setting back, always.  An application left permanently above everything
            // else is a worse fault than the one being fixed, and one they could not undo - the menu
            // item would then disagree with the window.
            setAlwaysOnTop(wasOnTop);

            if (!isActive() && attempt < 2)
            {
                raiseOnce(wasOnTop, attempt + 1);

                return;
            }

            // AND ONLY NOW THE KEYBOARD (fifth pass).
            //
            // After the flag is back, not before it: the restore above is a native window-style change
            // and it resets which component holds the focus, so a request made before it is undone by
            // it.  Posted rather than called, so that the style change has been processed first - the
            // same reason every other focus request in this class is posted.
            javax.swing.SwingUtilities.invokeLater(() ->
            {
                focusTheKeyboard();

                sayIfTheKeyboardIsLost();
            });
        });

        settle.setRepeats(false);
        settle.start();
    }

    /**
     * Says so in the log when nothing in this window ended up holding the keyboard (OB-170).
     *
     * **The question this asks is the one four rounds of fixes did not.**  The first version asked
     * whether the window was ACTIVE, and Adam's answer - "the message does NOT appear" - said it was,
     * while the letters still did nothing.  Being in front and having the keyboard are two facts, and
     * only the second one is what he is reporting.
     *
     * So this asks about the keyboard, and names what has it instead.  Its absence now means the
     * application believes everything is as it should be, which is a much stronger statement than the
     * old message's absence was.
     */
    private void sayIfTheKeyboardIsLost()
    {
        if (this.model == null) return;

        java.awt.Component owner = java.awt.KeyboardFocusManager
            .getCurrentKeyboardFocusManager().getFocusOwner();

        if (owner != null && javax.swing.SwingUtilities.isDescendingFrom(owner, this)) return;

        this.model.logf("ui.warnCouldNotTakeTheForeground",
            (isActive() ? "active" : "not active") + ", "
            + (owner == null ? "nothing has the keyboard"
                             : "the keyboard is on " + owner.getClass().getSimpleName()));
    }

    /**
     * Puts the keyboard on the tabbed pane, unless somebody is TYPING somewhere in this window.
     *
     * **The condition is what makes this safe to run on every activation.**  Without it, alt-tabbing
     * away from a half-typed line and back would take the caret out of it every time - which is a
     * worse fault than the one being fixed, and the reason this is not simply called unconditionally.
     *
     * **And the condition is about typing, not about focus.**  The first version of it deferred to
     * anything in this window that held the focus, and that is too generous by exactly the width of
     * the bug: focus resting on a label, a button or a scroll pane consumes no letters, so leaving it
     * there is leaving the window without a keyboard while looking like politeness.  Adam reported
     * OB-170 against a build whose start-up request had in fact been granted, which is what that looks
     * like from outside - and the test written for it went red with the fix in, holding a JLabel.
     *
     * A text component is the one case where taking the focus destroys something a person has done.
     * There are two in this window that can hold it - the log area and the JSON pane - and both can be
     * clicked into and typed in.
     */
    private void focusTheKeyboard()
    {
        if (KeyboardTab == null) return;

        java.awt.Component owner = java.awt.KeyboardFocusManager
            .getCurrentKeyboardFocusManager().getFocusOwner();

        if (owner instanceof javax.swing.text.JTextComponent
            && javax.swing.SwingUtilities.isDescendingFrom(owner, this)) return;

        KeyboardTab.requestFocusInWindow();
    }

    
    /**
     * Shows or hides the menu bar depending on the user's preference
     */
    private void displayMenuBar()
    {
        int barHeight = this.mainMenuBar.getHeight(); // 23
        
        int minHeight = this.getMinimumSize().height;
        int maxHeight = this.getMaximumSize().height;
        int prefHeight = this.getPreferredSize().height;
        int sizeHeight = this.getSize().height;

        if (this.mainMenuBar.isVisible() && !prefs.getBoolean(MENUBAR_SETTING_PREF, true))
        {
            this.mainMenuBar.setVisible(false);
            
            setMinimumSize(new java.awt.Dimension(this.getMinimumSize().width, minHeight - barHeight));
            setPreferredSize(new java.awt.Dimension(this.getPreferredSize().width, prefHeight - barHeight));            
            setMaximumSize(new java.awt.Dimension(this.getMaximumSize().width, maxHeight - barHeight));
            setSize(new java.awt.Dimension(this.getSize().width, sizeHeight - barHeight));

            revalidate();
            repaint();
        }
        else if (!this.mainMenuBar.isVisible() && prefs.getBoolean(MENUBAR_SETTING_PREF, true))
        {            
            setMaximumSize(new java.awt.Dimension(this.getMaximumSize().width, maxHeight + barHeight));
            setPreferredSize(new java.awt.Dimension(this.getPreferredSize().width, prefHeight + barHeight));
            setMinimumSize(new java.awt.Dimension(this.getMinimumSize().width, minHeight + barHeight));
            setSize(new java.awt.Dimension(this.getSize().width, sizeHeight + barHeight));
            
            this.mainMenuBar.setVisible(true);

            revalidate();
            repaint();
        }
    }
    
    /**
     * Updates the latency value
     * @param latency
     */
    @Override
    public void updateLatency(double latency)
    { 
        if (PING_INTERVAL > 0)
        {
            javax.swing.SwingUtilities.invokeLater(() ->
            {
                this.latencyLabel.setText(
                    I18n.f(
                        "ui.labelNetworkLatency",
                        (this.model.isCS3() ? "3" : "2"),
                        String.format("%.0f", latency)
                    )
                );

                this.latencyLabel.setForeground(latency > PING_ORANGE ? (latency > PING_RED ? Color.RED : Color.MAGENTA) : Color.BLACK);
            });
            
            this.checkAutoLayoutLatency(latency);
        }        
    }
    
    /**
     * Turns off the power in autonomy mode when the set latency limit is exceeded
     * @param latency 
     */
    private void checkAutoLayoutLatency(double latency)
    {
        if (model.getPowerState())
        {
            Layout l = model.getAutoLayout();

            if (l != null && l.isRunning() && l.getMaxLatency() > 0 && latency > l.getMaxLatency())
            {
                this.model.logf(
                    "ui.errorPowerOffLatencyExceeded",
                    l.getMaxLatency()
                );

                this.model.stop();

                javax.swing.SwingUtilities.invokeLater(() ->
                {
                    JOptionPane.showMessageDialog(
                        this,
                        I18n.f("ui.errorPowerOffLatencyExceededDialog", l.getMaxLatency())
                    );
                });
            }
        }
    }
    
    /**
     * Self-contained method to initialize a blank layout
     * @param folderName
     * @param verify
     */
    public void createAndApplyEmptyLayout(String folderName, boolean verify)
    {
        boolean proceed;

        if (!verify)
        {
            proceed = true;
        }
        else
        {
            // Attempt to create an empty layout if needed
            int dialogResult = JOptionPane.showOptionDialog(
                this,
                I18n.f(
                    "layout.ui.confirmInitializeTrackDiagram",
                    new File(folderName).getAbsolutePath()
                ),
                I18n.t("layout.ui.dialogCreateNewTrackDiagram"),
                JOptionPane.YES_NO_OPTION,
                JOptionPane.PLAIN_MESSAGE,
                null,
                YES_NO_OPTS,
                YES_NO_OPTS[0]
            );

            proceed = (dialogResult == JOptionPane.YES_OPTION);
        }

        if (proceed)
        {
            javax.swing.SwingUtilities.invokeLater(() ->
            {
                try
                {
                    this.model.logf("layout.ui.infoInitializingDemoLayout");

                    String path = this.initializeEmptyLayout(folderName);

                    if (path != null)
                    {
                        this.model.logf("layout.ui.infoLayoutInitializedAt", path);
                        prefs.put(LAYOUT_OVERRIDE_PATH_PREF, path);

                        // The editing controls answer differently now (OB-126): this is what decides whether
                        // there is a layout of his own to edit.
                        applyLayoutEditingAvailability();

                        this.syncWithCS2();
                        this.repaintLoc();
                    }

                    if (!this.model.getLayoutList().isEmpty())
                    {
                        this.initializeTrackDiagram(false);
                    }
                    else
                    {
                        this.model.logf("layout.ui.errorInitializeDemoLayout");
                        JOptionPane.showMessageDialog(
                            this,
                            I18n.t("layout.ui.errorInitializeDemoLayout")
                        );
                    }
                }
                catch (Exception e)
                {
                    this.model.logf("layout.ui.errorCriticalInitializeDemoLayout", e.getMessage());
                    this.model.log(e);
                }

                this.initializeLocalLayoutMenuItem.setEnabled(true);
            });
        }
        else
        {
            this.initializeLocalLayoutMenuItem.setEnabled(true);
        }
    }
    
    /**
     * Shows the layout tab and re-loads the track diagram
     * @param showTab
     */
    synchronized public void initializeTrackDiagram(boolean showTab)
    {
        javax.swing.SwingUtilities.invokeLater(()->
        {
            this.LayoutList.setModel(new DefaultComboBoxModel(this.model.getLayoutList().toArray()));

            // The pages have just been replaced, so this is one of the few moments the answer moves.
            updateLayoutLoaded();

            // the pages just changed wholesale, so a session describing the old ones - and anything
            // still monitoring or capturing against it - has to go
            this.resetAutonomySession();

            // OB-093, Adam: "when using a CS2 layout and the autonomy tab is greyed out, the autonomy
            // checkbox is still visible on the track diagram page." resetAutonomySession greys the Auto
            // tab itself (setAutonomyDependentTabs(false)), but the diagram strip's checkbox is a
            // SEPARATE affordance driven by autonomyOverlayToggle.setLoaded, which every other caller
            // reaches through autonomySetupChanged/refreshAutonomyPrompt - the one this switch-source
            // path never called. The strip kept whatever "loaded" it last had, so a CS2 layout with no
            // stored autonomy diagram greyed the tab and left the checkbox offering to show an overlay
            // for nothing. Same question, asked here too.
            this.refreshAutonomyPrompt();

            if (!this.model.getLayoutList().isEmpty())
            {
                this.repaintLoc();
                this.repaintLayout(showTab, false);
            }
            else
            {
                this.model.logf(
                    "layout.ui.errorNoLayoutLoaded"
                );

                // And on screen, not only in the log (OB-103).
                //
                // Adam: "if we get Model error: no layout loaded., there is no UI error notice
                // shown." This is the end of switching to a Central Station layout or downloading
                // one - a thing he pressed, that appeared to do nothing. The log line is for
                // afterwards; the person who pressed the button is still sitting there.
                //
                // Worded for that moment rather than as the log's own sentence: "no layout loaded" is
                // a statement about the model, and what he needs is which of the two likely reasons
                // it is - the station not answering, or the station having no diagram on it.
                JOptionPane.showMessageDialog(this,
                    I18n.t("layout.ui.errorNoLayoutFromCentralStation"));
            }
        });
    }
    
    public LocomotiveSelector getLocSelector()
    {
        return this.selector;
    }
    
    private void switchF(int fn)
    {        
        if (this.activeLoc != null)
        {
            this.fireF(fn, !this.activeLoc.getF(fn));
        }
    }
    
    private void fireF(int fn, boolean state)
    {        
        if (this.activeLoc != null)
        {            
            if (this.activeLoc.isFunctionTimed(fn) > 0)
            {
                new Thread(() -> {
                    this.activeLoc.toggleF(fn, this.activeLoc.isFunctionTimed(fn) * 1000);
                }).start();
            }
            else if (this.activeLoc.isFunctionPulse(fn))
            {
                new Thread(() -> {
                    this.activeLoc.toggleF(fn, this.activeLoc.getPulseFunctionDuration());
                }).start();
            }
            else
            {
                new Thread(() -> {
                    this.activeLoc.setF(fn, state);
                }).start();
            }
        }
    }
    
