    /**
     * Returns a scaled locomotive image
     * @param url
     * @param size
     * @return
     * @throws IOException 
     */
    public Image getLocImage(String url, int size) throws IOException, Exception
    {
        String key = url + Integer.toString(size);
        
        if (!TrainControlUI.getImageCache().containsKey(key))
        {
            Image img = ImageIO.read(new URL(url));
            
            if (img != null)
            {
                float aspect = (float) img.getHeight(null) / (float) img.getWidth(null);
                TrainControlUI.getImageCache().put(key, 
                    // img.getScaledInstance(size, (int) (size * aspect), 1)
                    // Higher quality scaling
                    ImageUtil.getScaledImage(ImageUtil.toTransparentBufferedImage(img), size, (int) (size * aspect))
                );
            }
        }

        return TrainControlUI.getImageCache().get(key);        
    }
    
    /**
     * Returns a scaled locomotive image
     * @param url
     * @param size
     * @param maxHeight
     * @return
     * @throws IOException 
     */
    public Image getLocImageMaxHeight(String url, int size, int maxHeight) throws IOException
    {
        String key = url + Integer.toString(size);
        
        if (!TrainControlUI.getImageCache().containsKey(key))
        {
            Image img = ImageIO.read(new URL(url));
            
            if (img != null)
            {
                float aspect = (float) img.getHeight(null) / (float) img.getWidth(null);
                
                // Limit maximum height
                if (size * aspect > maxHeight)
                {
                    size = (int) (size * (maxHeight / (size * aspect)));
                }
                
                TrainControlUI.getImageCache().put(key, 
                    // img.getScaledInstance(size, (int) (size * aspect), 1)
                    // Higher quality scaling
                    ImageUtil.getScaledImage(ImageUtil.toTransparentBufferedImage(img), size, (int) (size * aspect))
                );
            }
        }

        return TrainControlUI.getImageCache().get(key);        
    }
    
    /**
     * Repaints a locomotive button
     * @param b
     * @param l 
     * @param correspondingLocMappingNumber
     */
    private void repaintIcon(JButton b, Locomotive l, Integer correspondingLocMappingNumber)
    {
        noImageButton(b); // makes icons appear consistent on slow networks
        
        ImageLoader.submit(() -> 
        {
            if (b != null)
            {
                if (l == null)
                {
                    noImageButton(b);
                }
                else if (LOAD_IMAGES && l.getImageURL() != null && l.getImageURL().length() > 0)
                {
                    try 
                    {
                        BufferedImage locImage = (BufferedImage) getLocImage(l.getImageURL(), 66);
                      
                        // Generate shadow images
                        BufferedImage textImage = ImageUtil.generateImageWithText(b.getText(), Color.BLACK, b.getFont(), 
                            locImage.getWidth(null), locImage.getHeight(null), 2, 1);
                        
                        BufferedImage textImage2 = ImageUtil.generateImageWithText(b.getText(), Color.BLACK, b.getFont(), 
                            locImage.getWidth(null), locImage.getHeight(null), 1, -1);
                        
                        ImageIcon ic = new javax.swing.ImageIcon(
                            ImageUtil.mergeImages(ImageUtil.mergeImages(locImage, textImage), textImage2)
                        );
                        
                        // The active page has changed since this thread was called.  No need to update the UI.
                        if (this.locMappingNumber != correspondingLocMappingNumber)
                        {
                            return;
                        }
                        
                        // Check that the locomotive hasn't changed - only a sanity check if the latency is high
                        // l is known to be non-null, but the button may have been cleared while the image loaded
                        if (l.equals(this.getButtonLocomotive(b)))
                        {                     
                            b.setIcon(ic);  

                            b.setHorizontalTextPosition(SwingConstants.CENTER);

                            b.setForeground(Color.WHITE);
                            b.setContentAreaFilled(false);
                        }
                    } 
                    catch (Exception e)
                    {
                        noImageButton(b);

                        this.model.logf(
                            "ui.errorFailedToLoadImage",
                            l.getImageURL()
                        );

                        this.model.log(e);
                    }
                }
                else
                {
                    noImageButton(b);
                }
            }
        });
    }
    
    public ExecutorService getImageLoader()
    {
        return this.ImageLoader;
    }

    /**
     * Re-applies the caption rule to every label the diagram currently holds.
     *
     * Visibility is normally decided once, as each label is registered. This is for the moments when
     * the ANSWER changes without the labels being rebuilt - the setting being toggled, and a
     * configuration being loaded or unloaded, which changes which stations autonomy can choose.
     */
    void refreshCaptionVisibility()
    {
        javax.swing.SwingUtilities.invokeLater(() ->
        {
            for (java.util.Map.Entry<org.traincontrol.automationui.TileGraph.TileKey, Set<JLabel>>
                square : layoutStations.entrySet())
            {
                boolean visible = captionShouldShow(square.getKey());

                for (JLabel label : square.getValue()) label.setVisible(visible);
            }
        });
    }

    /**
     * Whether the routing dropdown is being put back by us rather than chosen by a person (RC-B11).
     *
     * A JComboBox fires an ActionEvent from setSelectedIndex, so restoring the control re-enters the
     * listener that asked for the restore.  Unguarded that is a second dialog on top of the first, and
     * it is the whole of what "safely restore the current setting" meant.
     *
     * Its checkbox siblings need nothing of the kind - setSelected fires no ActionEvent - which is why
     * they could restore in one line and this could not.
     *
     * Neither volatile nor synchronized: every read and every write is on the event thread, which is
     * also the only thread that can deliver the event it guards.
     */
    private boolean restoringRoutingLogic = false;

    /**
     * Puts what the chosen routing rule DOES onto the control that chooses it (OB-163).
     *
     * Every rule has an explanation written for it and translated into all eight languages -
     * `autolayout.ui.tooltip.pathPreferenceFEWEST_STATIONS` and its siblings - and until this method
     * existed nothing read a single one of them.  The dropdown was built from the names alone and
     * carried the general sentence about what the control is for, so seventy-two written sentences
     * were unreachable on the one control where ten similarly-worded options have to be told apart.
     *
     * It also hid that "Completely at Random" had no explanation written at all, which was obvious
     * the moment the text was on screen.
     *
     * Called from the three places the selection can change: the build, a person choosing, and
     * restoreRoutingLogicSelection - which holds a flag that stops the listener running, so it cannot
     * rely on the second of those.
     */
    private void refreshRoutingLogicTooltip()
    {
        if (algorithmType == null) return;

        String general = I18n.t("ui.main.tooltip.routingLogic");

        int at = algorithmType.getSelectedIndex();

        if (at < 0 || at >= ROUTING_ORDER.length)
        {
            algorithmType.setToolTipText(general);

            return;
        }

        // HTML so the two paragraphs wrap rather than running off the screen.  Both come from the
        // bundle and neither carries markup, so nothing here can be broken by a translation.
        algorithmType.setToolTipText("<html><p width=\"420\">" + general + "<br><br>"
            + I18n.t("autolayout.ui.tooltip.pathPreference" + ROUTING_ORDER[at].name())
            + "</p></html>");
    }

    /**
     * Puts the routing dropdown back to the rule the layout is actually using (RC-B11).
     *
     * Two callers wanting the same thing for different reasons: a refused change has to stop the
     * control reporting a rule that is not in force, and loading a configuration has to show that
     * configuration's rule rather than the last one seen.
     *
     * loadAutoLayoutSettings had its own copy of this loop and relied on the listener returning early
     * when nothing had changed.  That worked, and it was the same rule in two places - which is how
     * the two come to disagree.  This holds the flag instead, so the listener does not run at all.
     *
     * ROUTING_ORDER covers every PathPreference, so the loop always finds its rule; one it could not
     * find leaves the control alone, which is the right way to fail - a dropdown showing the previous
     * rule is wrong, and one showing an arbitrary rule is wrong AND convincing.
     */
    private void restoreRoutingLogicSelection()
    {
        if (algorithmType == null || this.model == null || !this.model.hasAutoLayout()) return;

        org.traincontrol.automation.Layout.PathPreference now =
            this.model.getAutoLayout().getPathPreference();

        this.restoringRoutingLogic = true;

        try
        {
            for (int at = 0; at < ROUTING_ORDER.length; at++)
            {
                if (ROUTING_ORDER[at] == now)
                {
                    algorithmType.setSelectedIndex(at);

                    // Inside the flag, which suppresses the listener - so the tooltip has to be asked
                    // for here as well or a restored selection keeps the refused rule's description
                    // (OB-163).
                    refreshRoutingLogicTooltip();

                    return;
                }
            }
        }
        finally
        {
            this.restoringRoutingLogic = false;
        }
    }

    /**
     * Fills in the routing-logic dropdown Adam put in the autonomy settings panel (MT-226).
     *
     * The control itself is his, added in the designer beside its label, so nothing here touches the
     * layout. An earlier version of this built its own panel and took the departure checkbox's slot
     * with GroupLayout.replace, because the slider's slot is pinned at 55 pixels and nothing can be
     * stacked under it - that looked wrong on screen, and getting the order of replace and re-parent
     * wrong in it stopped the application starting (LE2-A8). A component placed in the designer has
     * neither problem.
     *
     * The VALUE is not set here. loadAutoLayoutSettings pulls it from the live layout along with every
     * other autonomy setting, which is what makes it follow a configuration being switched.
     */
    private void mountRoutingLogic()
    {
        if (algorithmType == null) return;

        // Translated at runtime.  The designer wrote the label's text into the form in English, and
        // the form is not this class's file to edit.
        if (jLabel2 != null)
        {
            jLabel2.setText(I18n.t("ui.main.routingLogic"));
            jLabel2.setToolTipText(I18n.t("ui.main.tooltip.routingLogic"));
        }

        algorithmType.removeAllItems();

        for (org.traincontrol.automation.Layout.PathPreference option : ROUTING_ORDER)
        {
            algorithmType.addItem(I18n.t("autolayout.ui.pathPreference" + option.name()));
        }

        // CAPPED AT THE WIDTH IT IS ALIGNED TO (Adam: "cap the length at the width that it is aligned
        // to in the editor, 230px").
        //
        // Its slot is laid out at GroupLayout.PREFERRED_SIZE, so the control asks for whatever its
        // widest ITEM needs - and the rule names are sentences, so it grew past the slider it sits
        // under. Fixed here rather than in the designer because the width belongs to the text this
        // code puts in, and that text changes with the language.
        java.awt.Dimension capped = new java.awt.Dimension(230,
            algorithmType.getPreferredSize().height);

        algorithmType.setPreferredSize(capped);
        algorithmType.setMaximumSize(capped);

        // The full name still reaches the user, on the control that was too narrow to show it - and
        // with it what the chosen rule actually does (OB-163).
        refreshRoutingLogicTooltip();

        algorithmType.addActionListener(event ->
        {
            // OUR OWN RESTORE, NOT A PERSON (RC-B11).
            //
            // Checked out here rather than inside the invokeLater below, because setSelectedIndex
            // delivers this event synchronously and the flag is only held for that call.
            if (this.restoringRoutingLogic) return;

            if (this.model == null || !this.model.hasAutoLayout()
                || this.model.getAutoLayout() == null) return;

            javax.swing.SwingUtilities.invokeLater(() ->
            {
                if (this.model.hasAutoLayout())
                {
                    if (this.isAutonomyBusy())
                    {
                        this.applyAutoRouteListSelections();

                        // AND THE DROPDOWN GOES BACK, BEFORE THE MESSAGE (RC-B11).
                        //
                        // The rule is read as each path is chosen, so changing it while trains are
                        // running would leave the railway following two rules at once - hence the
                        // refusal.  What the refusal must not do is leave this control naming the rule
                        // it just refused: it is the only place the rule in force is reported.
                        //
                        // Before the dialog, not after.  The dialog is modal, so anything below it
                        // waits for the click - and the control would sit there contradicting the
                        // message for as long as the message was on screen.
                        restoreRoutingLogicSelection();

                        JOptionPane.showMessageDialog(this,
                            I18n.t("autolayout.ui.errorWaitForActiveLocomotivesToStop"));
                    }
                    else
                    {
                        int at = algorithmType.getSelectedIndex();

                        if (at < 0 || at >= ROUTING_ORDER.length) return;

                        org.traincontrol.automation.Layout.PathPreference option = ROUTING_ORDER[at];

                        // Nothing to do, and saying so would write the setup on every refresh.
                        if (this.model.getAutoLayout().getPathPreference() == option) return;

                        this.model.getAutoLayout().setPathPreference(option);

                        // And the tooltip follows the choice (OB-163)
                        refreshRoutingLogicTooltip();

                        // Said out loud when it cannot be kept.  A rule that applies now and reverts
                        // on the next start is the shape of "it did not save" that costs an hour to
                        // work out (LE-B5).
                        //
                        // true: somebody just chose this from the dropdown.
                        if (!persistPathPreference(option, true))
                        {
                            this.model.log(I18n.f("autolayout.warnRoutingRuleNotStored",
                                I18n.t("autolayout.ui.pathPreference" + option.name())));
                        }
                    }
                }
            });
        });
    }

    /**
     * The order the routing rules are offered in, and the index the dropdown speaks.
     *
     * The default first - which is the behaviour every existing railway already has - then the
     * measured choices in pairs, each rule beside its opposite, so the symmetry is visible rather than
     * something to work out from six similar labels.
     */
    private static final org.traincontrol.automation.Layout.PathPreference[] ROUTING_ORDER =
    {
        org.traincontrol.automation.Layout.PathPreference.RANDOM,
        org.traincontrol.automation.Layout.PathPreference.RANDOM_ANY_STATION,
        org.traincontrol.automation.Layout.PathPreference.FEWEST_STATIONS,
        org.traincontrol.automation.Layout.PathPreference.MOST_STATIONS,
        org.traincontrol.automation.Layout.PathPreference.SHORTEST_LENGTH,
        org.traincontrol.automation.Layout.PathPreference.LONGEST_LENGTH,
        org.traincontrol.automation.Layout.PathPreference.FEWEST_POINTS,
        org.traincontrol.automation.Layout.PathPreference.MOST_POINTS,
        org.traincontrol.automation.Layout.PathPreference.LEAST_RECENTLY_VISITED,
        org.traincontrol.automation.Layout.PathPreference.BALANCED_PRIORITY
    };
    /**
     * Writes the routing rule into the configuration it belongs to (LE-B5).
     *
     * ASKS getAutonomySession() RATHER THAN THE FIELD. SV-B2 forbids the getter in the layout-index
     * write path, because it is a lazy builder that parses every page, runs the caption migration -
     * which writes to disk - and can raise a dialog on the event thread. None of that applies to a
     * deliberate click on a menu, which is the context the builder exists to serve; and the field
     * alone is null after every diagram edit, which is precisely when a choice made here went nowhere.
     *
     * @param option the rule chosen
     * @param mayBuildSession true only when a person just clicked something. The session getter is a
     *        lazy builder that parses every page, runs the caption migration - which writes to disk -
     *        and can raise a dialog; a settings refresh must not do any of that, so it passes false
     *        and settles for the session that already exists (LE2-C16).
     * @return true when it was stored, false when there was nothing to store it in
     */
    private boolean persistPathPreference(org.traincontrol.automation.Layout.PathPreference option,
        boolean mayBuildSession)
    {
        try
        {
            // THE FIELD WHEN NOBODY CLICKED, THE BUILDER WHEN THEY DID (LE2-C16).
            //
            // LE-B5 justified getAutonomySession() here on the grounds that a menu click is not the
            // layout-index write path SV-B2 bans it from. That was true of a click. It is not true of
            // loadAutoLayoutSettings, which has fourteen callers - every autonomy settings checkbox
            // among them - and which now reaches this through the migration. A lazy builder that
            // parses every page, can write to disk and can raise a dialog must not run from a settings
            // refresh, so the caller says which context it is.
            org.traincontrol.automationui.AutonomySession session = mayBuildSession
                ? getAutonomySession() : autonomySession;

            return session != null && session.setGlobal("pathPreference", option.name());
        }
        catch (Exception e)
        {
            if (this.model != null) this.model.log(e);

            return false;
        }
    }
    /**
     * Whether this session has already carried the pre-3.0.0 routing preference across (RC-A8).
     *
     * Not derivable from the state: see migrateStoredPathPreference, where both ways of reading the
     * running layout give the wrong answer on the second call.
     */
    private boolean pathPreferenceCarried = false;

    /**
     * Carries a routing choice made before it lived in the configuration (LE-B2).
     *
     * Until this became a per-configuration setting the choice was a java Preference, read at startup
     * and pushed into a static on Layout. Removing that left an existing user's choice on disk with
     * nothing reading it: they got RANDOM after the upgrade, silently, and - before LE-B1 - a menu that
     * agreed.
     *
     * Moved once and the old key deleted, so it cannot come back later and overrule a choice made
     * since. Only when the configuration does not already carry one: a configuration that has been
     * given a rule has already answered this question.
     *
     * @param live the loaded layout, or null when there is none yet
     */
    private void migrateStoredPathPreference(org.traincontrol.automation.Layout live)
    {
        if (live == null) return;

        // The key as it was spelled before the move.  Written out rather than named, because the
        // constant is gone and reintroducing it would suggest something still writes it.
        final String legacy = "AutonomyPathPreference";

        String was = prefs.get(legacy, null);

        if (was == null) return;

        // ALREADY CARRIED, ONCE, THIS SESSION (RC-A8).
        //
        // The flag is here because the STATE cannot answer the question, in either direction.  On the
        // second call through this method, `live` holds a non-RANDOM rule - and that is either the
        // answer read out of the user’s own autonomy.json, which must not be overwritten, or the
        // value THIS METHOD wrote a moment ago, which must not be mistaken for the configuration
        // having answered.  RC-A2 read it the first way and deleted the key; reading it the second way
        // pushes the pre-upgrade rule over the file’s own answer on every settings refresh.
        //
        // Both readings are wrong because the question is not about the state.  It is "have I done
        // this yet", and a flag is the honest way to ask it.
        if (this.pathPreferenceCarried) return;

        // THE STORED ANSWER, NOT THE LIVE ONE (RC-A2).
        //
        // This asked live.getPathPreference(), and on the second call through here that is what THIS
        // METHOD wrote into memory on the first. So the second call found a non-RANDOM value, decided
        // the configuration had answered, and deleted the legacy key with nothing ever stored -
        // leaving RANDOM for ever, and making the promise in the javadoc above, that a migration which
        // cannot run today runs tomorrow, impossible to keep. Its own in-memory write closed the door.
        //
        // The second call is one checkbox away: loadAutoLayoutSettings has fourteen callers and
        // reaches this from every one of them.
        //
        // The field rather than getAutonomySession(), for the reason persistPathPreference is passed
        // false: this runs from a settings refresh, and the getter is a lazy builder that parses every
        // page, writes to disk and can raise a dialog (LE2-C16).
        org.traincontrol.automationui.AutonomySession stored = this.autonomySession;

        // THE LOADED LAYOUT’S OWN ANSWER COUNTS TOO (RC-A8).
        //
        // Layout.fromJSON reads pathPreference, so a legacy user’s autonomy.json can carry a rule
        // even though getGlobal cannot see it - there is no active configuration for it to look in.
        // Checked before the store rather than after, because it is the cheaper question and the one
        // that is true for the whole legacy population.
        //
        // Safe to read here only because of the flag above: on a second call this would be reading
        // this method’s own writing, and the flag has already returned by then.
        if (live.getPathPreference() != org.traincontrol.automation.Layout.PathPreference.RANDOM)
        {
            prefs.remove(legacy);

            return;
        }

        if (stored != null && stored.getGlobal("pathPreference") != null)
        {
            // The configuration has its own answer, so the old one is stale and may go.  This also
            // covers a choice made from the dropdown SINCE a failed migration: the stored answer is
            // that choice, and the pre-upgrade key must not come back and overrule it.
            prefs.remove(legacy);

            return;
        }

        try
        {
            org.traincontrol.automation.Layout.PathPreference option =
                org.traincontrol.automation.Layout.PathPreference.valueOf(was);

            live.setPathPreference(option);

            // Before the persist, not after: the carry has happened either way, and what
            // persistPathPreference answers is only whether it is DURABLE yet.
            this.pathPreferenceCarried = true;

            // THE OLD KEY GOES ONLY ONCE THE NEW HOME HAS IT (LE-B5).
            //
            // This deleted it first and persisted afterwards, so a run where nothing could be stored -
            // no session, no active configuration - threw away the only durable copy of a choice made
            // before the setting moved. The next restart was RANDOM, for ever. Kept until it has
            // landed, so a migration that cannot run today runs tomorrow.
            // false: this runs from loadAutoLayoutSettings, which is a refresh and not a click.
            if (persistPathPreference(option, false)) prefs.remove(legacy);
        }
        catch (Exception e)
        {
            // A choice this build does not have, or a setup that would not save.  The key stays, so
            // this can be tried again.
            if (this.model != null) this.model.log(e);
        }
    }

    /**
     * Syncs with the Central Station without freezing the interface, and says that it is working.
     *
     * The sync fetches and parses several files over HTTP and then REPLACES the locomotive, route and
     * accessory databases.  Called straight from the event thread - which is what sixteen call sites in
     * this class did - the whole interface stops responding for as long as the network takes, with
     * nothing on screen to say why.  On a station that has been switched off that is the connect
     * timeout, twice.
     *
     * So the fetch runs on a worker and a modal spinner stands in front of it.  Modal for a reason
     * beyond politeness: the databases are swapped wholesale, and a user clicking around during the
     * swap is clicking at things that are about to be replaced underneath them.
     *
     * WHAT THIS DOES NOT DO, and what a full fix would.  Modality blocks input, not painting - a
     * repaint that lands mid-swap can still draw from a half-replaced database.  Closing that properly
     * means the fetch/apply split recorded in the deferred-optimisations list: phase one fetches and
     * parses into detached structures off the event thread, phase two swaps them in on it, in one step.
     * That is a restructuring of two hundred lines of database reconciliation - the part that must not
     * break - and is deliberately not attempted here.  This removes the freeze and the silence, which
     * is what a user experiences; the remaining hazard is a paint, is brief, and has never been
     * reported.
     *
     * Off the event thread this is a plain call, because there is nothing to block and nothing to show.
     *
     * ONE AT A TIME.  Moving the work off the event thread also made two syncs possible where the old
     * code made them impossible: the event thread WAS the swap, so a second one could not begin until
     * the first returned.  A modal dialog runs a nested event loop, which blocks input but happily
     * dequeues runnables already posted - and three call sites reach here from invokeLater or a raw
     * thread.  Two workers inside the same two hundred lines of database reconciliation is a worse
     * problem than the one this method set out to solve, so a second caller is turned away rather than
     * queued.  Turned away rather than made to wait because the callers are all "sync after I changed
     * something", and a sync already running will pick that change up.
     *
     * @return whatever syncWithCS2 returned, so a caller can still read it, or SYNC_ALREADY_RUNNING
     *         when another sync was in progress - which is NOT a failure and must not be reported as
     *         one
     */
    public int syncWithCS2()
    {
        if (!syncInFlight.compareAndSet(false, true))
        {
            this.log(I18n.t("ui.infoSyncAlreadyRunning"));

            return SYNC_ALREADY_RUNNING;
        }

        try
        {
            // this.model, NOT this.  Both calls in this method were rewritten to this.syncWithCS2() by
            // the same bulk edit that routed the sixteen call sites through here, which made the
            // wrapper call itself: off the event thread immediately, and on it via the worker, which is
            // also off it.  Every Sync was a StackOverflowError.
            // BEHIND THE SPINNER EITHER WAY (OB-140).
            //
            // Adam: "the hourglass flyover isn't shown when syncing the CS database from the
            // Locomotives JMenu, locomotive database popup, or the Functions Jmenu."
            //
            // Those three doors are not special - they are simply the ones that sync from a background
            // thread, which is the correct thing for them to do, and this method's answer to being off
            // the event thread was to fetch the whole Central Station database in silence. Whether the
            // user is told that something slow is happening depended on which thread the door happened
            // to be on, which is not a distinction anybody can see.
            //
            // The work stays HERE rather than moving to a worker, because the caller wants the answer:
            // `BusyDialog.run` would hand the sync to a second thread and return at once, and the
            // result would arrive after this method had already returned -1 to whoever asked.
            // Every play button comes back (FR-043).  Sixteen doors sync through this method, which
            // is why the spinner in OB-140 went here too rather than into the three that were reported.
            resetRouteSpinners();

            if (!javax.swing.SwingUtilities.isEventDispatchThread())
            {
                BusyDialog.Closer busy =
                    BusyDialog.showUntilClosed(this, I18n.t("ui.busySyncingWithCS"));

                try
                {
                    return this.model.syncWithCS2();
                }
                finally
                {
                    // In a finally for the reason BusyDialog itself gives about its own continuation:
                    // work that throws would otherwise leave a modal window on screen with no close
                    // button and nothing left alive to dismiss it.
                    busy.close();
                }
            }

            // Held in an array because a lambda cannot assign a local, and read after the dialog
            // closes - BusyDialog.run does not return until the worker has disposed it
            final int[] result = {-1};

            BusyDialog.run(this, I18n.t("ui.busySyncingWithCS"),
                () -> result[0] = this.model.syncWithCS2(), null);

            return result[0];
        }
        finally
        {
            syncInFlight.set(false);
        }
    }

    /**
     * The three settings that decide what an autonomy setup DRAWS on the ordinary track diagram.
     *
     * Adam, 2026-08-27: "move 'Grey Station Labels' into the Autonomy Preferences menu subsection,
     * group with the new one and with Show Inactive Labels, and add a divider above."
     *
     * They belong together because they answer one question, and two of them were in different menus.
     * Grey Station Labels sat under Layout, which is where the DIAGRAM is configured - but the colour
     * of a station caption is not a fact about the diagram, it is a fact about what autonomy puts on
     * top of one.
     *
     * One method rather than three, so the divider and the items it introduces cannot drift apart, and
     * so the order of the group is written here rather than being whatever order three unrelated calls
     * happened to run in.
     *
     * NONE OF THEM NEEDS A SETUP TO BE LOADED. `repaintLayout` rebuilds a diagram that exists either
     * way; `refreshCaptionVisibility` walks the captions currently held, of which there are none; and
     * the arrows go through `showStaticAutonomyLayer`, which clears the whole layer and returns when
     * there is no session, no graph or no configuration. Each is handed the state it should act on
     * rather than an assumption that autonomy is there.
     */
    private void buildDiagramDrawingMenu()
    {
        if (autonomyToolbarMenu == null) return;

        // The divider Adam asked for, above the group rather than inside it.
        autonomyToolbarMenu.addSeparator();

        // Built here rather than in the form: the form is generated, and a hand-written item in a
        // generated block is a change the next round trip through the designer would silently drop.
        //
        // On by default. A caption vanishing is a worse surprise than a crowded diagram, and somebody
        // who has not asked for this should see the railway as they drew it.
        final javax.swing.JCheckBoxMenuItem show = new javax.swing.JCheckBoxMenuItem(
            I18n.t("autolayout.ui.menuShowInactiveLabels"),
            prefs.getBoolean(SHOW_INACTIVE_LABELS_PREF, SHOW_INACTIVE_LABELS_DEFAULT));

        show.setToolTipText(I18n.t("autolayout.ui.tooltip.menuShowInactiveLabels"));

        show.addActionListener(event ->
        {
            prefs.putBoolean(SHOW_INACTIVE_LABELS_PREF, show.isSelected());

            // Applied to what is already drawn, not left for the next rebuild.  The grid rebuilds for
            // a dozen reasons and none of them is this one, so without this the setting appeared to do
            // nothing until something unrelated happened to redraw the diagram.
            refreshCaptionVisibility();
        });

        autonomyToolbarMenu.add(show);

        this.greyStationLabelsMenuItem =
            new javax.swing.JCheckBoxMenuItem(I18n.t("ui.main.toolbar.greyStationLabels"));

        this.greyStationLabelsMenuItem.setToolTipText(
            I18n.t("ui.main.toolbar.tooltip.greyStationLabels"));

        this.greyStationLabelsMenuItem.setSelected(prefs.getBoolean(STATION_LABELS_GREY, false));

        this.greyStationLabelsMenuItem.addActionListener(event ->
        {
            prefs.putBoolean(STATION_LABELS_GREY, this.greyStationLabelsMenuItem.isSelected());

            // The grid, not a repaint: a caption's colour is chosen when it is built, in the same
            // breath as its text, so nothing changes on screen until the diagram is built again.
            repaintLayout();
        });

        autonomyToolbarMenu.add(this.greyStationLabelsMenuItem);

        this.restrictionArrowsMenuItem =
            new javax.swing.JCheckBoxMenuItem(I18n.t("ui.main.toolbar.restrictionArrows"));

        this.restrictionArrowsMenuItem.setToolTipText(
            I18n.t("ui.main.toolbar.tooltip.restrictionArrows"));

        this.restrictionArrowsMenuItem.setSelected(
            prefs.getBoolean(DIAGRAM_RESTRICTION_ARROWS, true));

        this.restrictionArrowsMenuItem.addActionListener(event ->
        {
            prefs.putBoolean(DIAGRAM_RESTRICTION_ARROWS,
                this.restrictionArrowsMenuItem.isSelected());

            // The ANNOTATION layer, not the grid: an arrow is drawn over a tile that is already built.
            //
            // Handed the OVERLAY'S OWN STATE rather than true, which is what makes this safe with no
            // setup loaded. showStaticAutonomyLayer clears the layer and returns when there is no
            // session, no graph or no active configuration - and asking it to show nothing, because
            // the overlay is off or has not been built yet, lands in exactly the same place. The
            // expression is the one the autonomy refresh uses for the same reason.
            showStaticAutonomyLayer(
                autonomyOverlayToggle != null && autonomyOverlayToggle.isOverlayShown());
        });

        autonomyToolbarMenu.add(this.restrictionArrowsMenuItem);
    }

    /**
     * "Save diagram as a picture", on the Layout menu.
     *
     * Built by hand rather than in the form editor, so this whole feature is one method and one class
     * and can be read in one place.
     *
     * Asks which page and how big, because both answers are the user's: a manual wants the whole
     * layout at a size somebody can read, and a forum post wants something smaller.
     */
    private void buildDiagramExportMenu()
    {
        if (layoutMenu == null) return;

        // One item, for the page on screen.  There were two - this one and another that asked which
        // page - and the second earned its place only when the answer was not the page you are
        // looking at, which is rare enough not to be worth a permanent line in a menu.  Switch pages
        // and export again.
        javax.swing.JMenuItem active =
            new javax.swing.JMenuItem(I18n.t("layout.ui.menuExportActiveDiagram"));

        active.setToolTipText(I18n.t("layout.ui.tooltipExportActiveDiagram"));

        active.addActionListener(event -> exportDiagram(activeLayoutPage()));

        // BESIDE THE POP-OUT, not at the foot of the menu (Adam, 2026-08-28).
        //
        // It was appended behind a separator of its own, which left it below the Central Station
        // group - beside two items about talking to the station, which it has nothing to do with.
        // Both of these make a picture of the diagram in a window of their own.
        //
        // Looked up rather than counted: what sits above the pop-out changes as the headings and the
        // per-page submenu are mounted.
        int beside = indexOnLayoutMenu(popUpAllMenuItem);

        if (beside >= 0) layoutMenu.add(active, beside + 1);
        else layoutMenu.add(active);

        // Kept, so guardLayoutMenu can grey it by name (OB-128). The loop there reaches every child
        // while an editor is open; deciding availability needs the item itself.
        exportDiagramItem = active;
    }

    /** "Save Current Track Diagram as a Picture..." on the Layout menu - see guardLayoutMenu */
    private javax.swing.JMenuItem exportDiagramItem;

    /**
     * Asks which page, at what size, and where, and then writes it.
     *
     * The drawing happens OFF the event thread, behind a spinner.  It builds Swing components, which
     * may only be touched there - so it marshals those steps itself - but between them it WAITS for
     * tile images to be decoded, and those are applied on the event thread.  Holding that thread
     * would mean waiting for work that cannot happen until the wait is over.
     */
    /**
     * The diagram page currently on screen, or null when there is none.
     *
     * The selector's own answer rather than a remembered one, so it cannot disagree with what the
     * user is looking at.
     */
    private String activeLayoutPage()
    {
        Object showing = this.LayoutList == null ? null : this.LayoutList.getSelectedItem();

        return showing == null ? null : showing.toString();
    }

    /**
     * Writes a diagram page to a picture file.
     *
     * @param page the page to draw, or null to ask which one.  The active-page item passes the page
     *        so that the common case - "a picture of what I am looking at" - is one click and no
     *        question, while the menu still offers any other page for the times it is not
     */
    private void exportDiagram(String page)
    {
        java.util.List<String> pages = this.model.getLayoutList();

        if (pages == null || pages.isEmpty())
        {
            JOptionPane.showMessageDialog(this, I18n.t("layout.ui.errorNoDiagramToExport"));

            return;
        }

        // A page that is no longer there - a rename or a reload between opening the menu and choosing
        // from it - falls back to asking rather than exporting the wrong thing or nothing
        if (page != null && !pages.contains(page)) page = null;

        if (page == null)
        {
            page = (String) JOptionPane.showInputDialog(this,
                I18n.t("layout.ui.promptWhichDiagram"), I18n.t("layout.ui.menuExportDiagram"),
                JOptionPane.PLAIN_MESSAGE, null, pages.toArray(), pages.get(0));
        }

        if (page == null) return;

        // Large or small, rather than a number to invent.  There are two answers anybody wants -
        // what the screen shows, and something that reads well in a document - and a free box asked
        // the user to pick a pixel size for a tile, which is not a question about their railway.
        Object[] sizes = {
            I18n.f("layout.ui.diagramSizeLarge", DiagramExport.DEFAULT_TILE_SIZE),
            I18n.f("layout.ui.diagramSizeSmall", DiagramExport.SCREEN_TILE_SIZE)
        };

        Object size = JOptionPane.showInputDialog(this, I18n.t("layout.ui.promptDiagramSizeChoice"),
            I18n.t("layout.ui.menuExportActiveDiagram"), JOptionPane.PLAIN_MESSAGE, null,
            sizes, sizes[0]);

        if (size == null) return;

        int tileSize = sizes[1].equals(size)
            ? DiagramExport.SCREEN_TILE_SIZE : DiagramExport.DEFAULT_TILE_SIZE;

        javax.swing.JFileChooser chooser = new javax.swing.JFileChooser();

        chooser.setDialogTitle(I18n.t("layout.ui.menuExportDiagram"));

        // A sensible name that is also a legal one, since a page may be called anything at all
        chooser.setSelectedFile(new java.io.File(page.replaceAll("[^a-zA-Z0-9 _-]", "_") + ".png"));

        if (chooser.showSaveDialog(this) != javax.swing.JFileChooser.APPROVE_OPTION) return;

        java.io.File destination = chooser.getSelectedFile();

        if (!destination.getName().toLowerCase().endsWith(".png"))
        {
            destination = new java.io.File(destination.getParentFile(), destination.getName() + ".png");
        }

        final java.io.File writeTo = destination;
        final int pixels = tileSize;
        final String chosen = page;
        final Exception[] failed = new Exception[1];

        // Off the event thread, behind the spinner.  The render WAITS for tile images to be decoded,
        // and those are applied on the event thread - so holding it would mean waiting for work that
        // cannot happen until the wait is over.  It also takes long enough on a big layout to be worth
        // saying something about.
        BusyDialog.run(this, I18n.t("layout.ui.busyExportingDiagram"),
            () ->
            {
                try
                {
                    DiagramExport.writePng(this.model.getLayout(chosen), pixels, this, writeTo);
                }
                catch (Exception e)
                {
                    failed[0] = e;
                }
            },
            () ->
            {
                if (failed[0] != null)
                {
                    this.model.log(failed[0]);

                    JOptionPane.showMessageDialog(this,
                        I18n.f("layout.ui.errorDiagramExportFailed",
                            String.valueOf(failed[0].getMessage())));

                    return;
                }

                this.log(I18n.f("layout.ui.infoDiagramExported", writeTo.getAbsolutePath()));

                // The folder, not a dialog reciting the path.  Somebody who has just written a
                // picture wants the picture; being told where it is and having to go there is the
                // long way round, and every other file this application writes opens its folder.
                showFileExplorer(writeTo.getParentFile());
            });
    }

    /**
     * The route names with "new route" at the top, for the picker above.
     */
    private Object[] withNewFirst(java.util.List<String> routes)
    {
        java.util.List<String> out = new java.util.ArrayList<>();

        out.add(I18n.t("route.ui.frameNewRoute"));

        if (routes != null) out.addAll(routes);

        return out.toArray();
    }

    public ExecutorService getTileImageLoader()
    {
        return this.TileImageLoader;
    }

    /**
     * How many tile images are being decoded right now.
     *
     * Counted rather than inferred from the executor, because the pool has several threads: a task
     * submitted last can start before an earlier one finishes, so "the queue is empty" does not mean
     * "the work is done" and a trailing marker task would lie.
     */
    private final java.util.concurrent.atomic.AtomicInteger tilesDecoding
        = new java.util.concurrent.atomic.AtomicInteger();

    /**
     * What to run when the last decode finishes.  Drained on the EDT, so a listener never sees a
     * half-applied grid.
     */
    private final java.util.List<Runnable> tilesSettledListeners
        = java.util.Collections.synchronizedList(new java.util.LinkedList<Runnable>());

    /**
     * Whether every tile image is decoded, so a grid built now has nothing to wait for.
     *
     * The same question whenTilesSettled answers by callback, asked without one. A caller that only
     * wants to know whether to bother hiding anything cannot use the callback for it: with nothing
     * pending that runs on the NEXT event-thread pass, and the gap between now and then is exactly
     * the flicker of OB-109.
     *
     * @return true when no decode is outstanding
     */
    public boolean tilesAreSettled()
    {
        return tilesDecoding.get() == 0;
    }

    public void tileDecodeStarted()
    {
        tilesDecoding.incrementAndGet();
    }

    /**
     * One decode finished.  When it was the last, everything waiting is released.
     *
     * The release goes through invokeLater rather than running here, because "the decode is done" and
     * "the image is on the label" are different moments - the label applies it on the EDT - and a
     * listener that reveals the diagram wants the second one.  Posting from this thread puts the
     * release behind the label updates already queued.
     */
    public void tileDecodeFinished()
    {
        if (tilesDecoding.decrementAndGet() > 0) return;

        javax.swing.SwingUtilities.invokeLater(() ->
        {
            if (tilesDecoding.get() > 0) return;

            java.util.List<Runnable> waiting;

            synchronized (tilesSettledListeners)
            {
                waiting = new java.util.LinkedList<>(tilesSettledListeners);
                tilesSettledListeners.clear();
            }

            for (Runnable r : waiting) r.run();
        });
    }

    /**
     * Runs something once no tile image is still being decoded.
     *
     * Immediately - on the EDT - when nothing is pending, which is the second time a diagram is opened
     * and every tile comes from the cache.  Callers use this to avoid showing a diagram that is only
     * half drawn.
     *
     * @param whenDone what to run, on the EDT
     */
    public void whenTilesSettled(Runnable whenDone)
    {
        if (whenDone == null) return;

        // Registered UNDER the same lock the drain takes, and the count re-read inside it.
        //
        // This was check-then-act: read the count, then add the listener.  A decode finishing between
        // those two lines drained a list this listener had not joined yet, and nothing ever ran it -
        // so the diagram export waited its full thirty-second failsafe before drawing, once in a
        // while, for no reason it could report.
        synchronized (tilesSettledListeners)
        {
            if (tilesDecoding.get() > 0)
            {
                tilesSettledListeners.add(whenDone);
                return;
            }
        }

        javax.swing.SwingUtilities.invokeLater(whenDone);
    }

    @Override
    public void repaintLoc()
    {
        repaintLoc(false, null);
    }
    
    /**
     * Gets the locomotive name to display in pop-up window titles
     * @return 
     */
    public String getWindowTitleString()
    {
        // Show nothing if there is no active locomotive, or the setting is not selected
        if (this.activeLoc == null || this.model.getLocByName(this.activeLoc.getName()) == null || !this.activeLocInTitle.isSelected())
        {
            return "";
        }
        else
        {
            return " [" + this.activeLoc.getName() + " " + 
                    (this.activeLoc.getDirection() == Locomotive.locDirection.DIR_FORWARD ? ">>" : "<<") +
                    " " + this.activeLoc.getSpeed() + "%]";
        }
    }
        
    @Override
    synchronized public void repaintLoc(boolean force, List<Locomotive> updatedLocs)
    {     
        // Prevent concurrent calls
        for (Future<?> f : this.locFutures)
        {
            if (!f.isDone()) 
            {
                return;
            }
        }

        this.locFutures.clear();

        this.locFutures.add(
            this.LocRenderer.submit(() -> 
            { 
                javax.swing.SwingUtilities.invokeLater(() ->
                {
                    if (this.activeLoc != null 
                            && this.model.getLocByName(this.activeLoc.getName()) != null // If this loc no longer exists, don't display it
                    )
                    {           
                        // Only update if the active locomotive matches the event
                        if (updatedLocs == null || updatedLocs.contains(activeLoc))
                        {
                            String name = this.activeLoc.getName();

                            if (name.length() > MAX_LOC_NAME)
                            {
                                name = name.substring(0, MAX_LOC_NAME);
                            }
                            
                            // Pre-compute this so we can check if it has changed
                            // "Page " + this.currentButtonlocMappingNumber + " Button "
                            String locLabel = "<html><nobr>" + this.currentButton.getText() + " &#8226; " 
                                    + this.getPageName(currentButtonlocMappingNumber, false, false) + " &#8226; "
                                    + this.activeLoc.getDecoderTypeLabel() 
                                    + " " + this.model.getLocAddress(this.activeLoc.getName())
                                    + "</nobr></html>";
                                                        
                            // Display active locomotive in autonomy UI
                            String windowTitleString = getWindowTitleString();
                            
                            
                            for (LayoutPopupUI popup : this.popups)
                            {
                                popup.setTitle(popup.getLayoutTitle() + windowTitleString);
                            } 

                            // Only repaint icon if the locomotive is changed
                            // Visual stuff
                            if (!this.ActiveLocLabel.getText().equals(name) || !locLabel.equals(CurrentKeyLabel.getText()) || force)
                            {
                                // Do this outside of the queue b/c otherwise it would be delayed for the currently selected loc at app startup
                                repaintIcon(this.currentButton, this.activeLoc, currentButtonlocMappingNumber);

                                ImageLoaderLoc.submit(() -> 
                                {
                                    if (LOAD_IMAGES && this.activeLoc.getImageURL() != null)
                                    {
                                        String url = this.activeLoc.getImageURL();

                                        try 
                                        {
                                            ImageIcon icon = new javax.swing.ImageIcon(
                                                getLocImageMaxHeight(this.activeLoc.getImageURL(), LOC_ICON_WIDTH, LOC_ICON_HEIGHT)
                                                // getLocImage(this.activeLoc.getImageURL(), LOC_ICON_WIDTH)
                                            );
                                            
                                            // If the network is laggy, this could show an icon even though no loc is selected
                                            // Check to ensure there is still an active loc and it hasn't changed
                                            if (this.activeLoc != null && url != null && url.equals(this.activeLoc.getImageURL()))
                                            {
                                                locIcon.setIcon(icon);      
                                                locIcon.setText("");
                                                locIcon.setVisible(true);

                                                // And whether the mark belongs on THIS locomotive (C6).  Visibility was
                                                // decided on hover alone, so hovering one locomotive and then switching by
                                                // keyboard left the mark standing over a picture it had nothing to do with -
                                                // and clicking it did nothing at all, silently.
                                                // On the EDT (validator).  This block runs on
                                                // ImageLoaderLoc's pool, and getMousePosition takes
                                                // the AWT tree lock and can throw HeadlessException -
                                                // a RuntimeException the enclosing catch(IOException)
                                                // would not stop, killing the pool task.
                                                javax.swing.SwingUtilities.invokeLater(
                                                    () -> showCropOverlay());
                                            }
                                        }
                                        catch (IOException e)
                                        {
                                            if (this.activeLoc != null && url != null && url.equals(this.activeLoc.getImageURL()))
                                            {
                                                locIcon.setIcon(null);
                                                locIcon.setVisible(false);
                                            }
                                        }
                                    }
                                    else
                                    {
                                        // A PLACEHOLDER RATHER THAN NOTHING (FR-054).
                                        //
                                        // The panel used to go blank for a locomotive with no
                                        // picture, which reads as an icon that failed to load rather
                                        // than as one nobody has set.
                                        locIcon.setIcon(new javax.swing.ImageIcon(
                                            LocomotivePlaceholder.image(LOC_ICON_WIDTH)));

                                        locIcon.setText("");
                                        locIcon.setVisible(true);
                                    }
                                });

                                this.ActiveLocLabel.setText(name);

                                this.CurrentKeyLabel.setText(locLabel);

                                for (int i = 0; i < this.activeLoc.getNumF(); i++)
                                {
                                    final JToggleButton bt = this.rFunctionMapping.get(i);
                                    final int functionType = this.activeLoc.getFunctionType(i);

                                    bt.setVisible(true);
                                    bt.setEnabled(true);

                                    // Use "active" icons on the CS3, which look better
                                    String targetURL = this.activeLoc.getFunctionIconUrl(i, functionType, this.model.isCS3() || !this.model.getNetworkCommState(), true);

                                    final boolean hasCustom = this.activeLoc.getLocalFunctionImageURL(i) != null;

                                    bt.setHorizontalTextPosition(JButton.CENTER);
                                    bt.setVerticalTextPosition(JButton.CENTER);

                                    ImageLoaderLoc.submit(() -> 
                                    {
                                        try
                                        {
                                            if ((hasCustom || functionType > 0) && LOAD_IMAGES)
                                            {
                                                Image icon = getLocImage(targetURL, BUTTON_ICON_WIDTH);

                                                if (icon != null && this.activeLoc != null)
                                                {
                                                    bt.setIcon(
                                                        new javax.swing.ImageIcon(
                                                            icon
                                                        )
                                                    );

                                                    bt.setText("");                                    
                                                }
                                                else
                                                {
                                                    //bt.setText("F" + Integer.toString(fNo));
                                                }
                                            }
                                            else
                                            {
                                                bt.setIcon(null);
                                                bt.setText("");                                    
                                                //bt.setText("F" + Integer.toString(fNo));
                                            }
                                        }
                                        catch (Exception e)
                                        {
                                            this.model.logf(
                                                "ui.errorIconNotFound",
                                                targetURL
                                            );                  
                                            //bt.setText("F" + Integer.toString(fNo));
                                        } 
                                    });         
                                }

                                for (int i = this.activeLoc.getNumF(); i < NUM_FN; i++)
                                {
                                    this.rFunctionMapping.get(i).setVisible(true);
                                    this.rFunctionMapping.get(i).setEnabled(false);

                                    //this.rFunctionMapping.get(i).setText("F" + Integer.toString(i));
                                    this.rFunctionMapping.get(i).setText("");                                    
                                    this.rFunctionMapping.get(i).setIcon(null);
                                }

                                // Remember the active tab
                                int currentFIndex = FunctionTabs.getSelectedIndex();
                                
                                // Hide unnecessary function tabs
                                if (this.activeLoc.getNumF() < 20)
                                {
                                    FunctionTabs.remove(this.F20AndUpPanel);
                                }
                                else
                                {
                                    FunctionTabs.add("F20-F31", this.F20AndUpPanel);
                                    FunctionTabs.setSelectedIndex(currentFIndex);
                                }

                                this.Backward.setVisible(true);
                                this.Forward.setVisible(true);
                                this.SpeedSlider.setVisible(true);
                                this.FunctionTabs.setVisible(true);
                            }

                            // Loc state
                            if (this.activeLoc.goingForward())
                            {
                                this.Forward.setSelected(true);
                                this.Backward.setSelected(false);
                            }
                            else
                            {
                                this.Backward.setSelected(true);
                                this.Forward.setSelected(false);
                            }

                            for (int i = 0; i < this.activeLoc.getNumF(); i++)
                            {
                                this.rFunctionMapping.get(i).setSelected(this.activeLoc.getF(i));
                            }

                            for (int i = this.activeLoc.getNumF(); i < NUM_FN; i++)
                            {
                                this.rFunctionMapping.get(i).setSelected(this.activeLoc.getF(i));
                            }

                            this.SpeedSlider.setValue(this.activeLoc.getSpeed()); 
                        }
                    }
                    else
                    {
                        locIcon.setIcon(null);
                        locIcon.setText("");

                        // The mark belongs to the picture that was there; a locomotive with no icon
                        // has nothing to re-crop (FR-032).
                        if (cropOverlay != null) cropOverlay.setVisible(false);

                        this.ActiveLocLabel.setText(
                            I18n.t("loc.ui.labelNoLocomotiveClickHere")
                        );
                        
                        this.CurrentKeyLabel.setText("<html><nobr>" + this.currentButton.getText() + " &#8226; " 
                                + this.getPageName(currentButtonlocMappingNumber, false, false) + "</nobr></html>"    
                        );

                        this.Backward.setVisible(false);
                        this.Forward.setVisible(false);
                        this.SpeedSlider.setVisible(false);
                        this.FunctionTabs.setVisible(false);

                        for (int i = 0; i < NUM_FN; i++)
                        {
                            this.rFunctionMapping.get(i).setVisible(false);
                        }
                        
                        // Clear locomotive from graph UI title
                        
                        for (LayoutPopupUI popup : this.popups)
                        {
                            popup.setTitle(popup.getLayoutTitle()); 
                        }
                    }
                    
                    // Repaint mappings only if the updated locomotive is currently visible
                    if (updatedLocs == null || currentLocMapping().values().stream().anyMatch(updatedLocs::contains))
                    {
                        this.repaintMappings(updatedLocs, false);
                    }
                });
            })
        );
    }
    
    private Map<JButton, Locomotive> nextLocMapping()
    {
        return this.locMapping.get(this.locMappingNumber % this.numLocMappings);
    }
    
    private Map<JButton, Locomotive> prevLocMapping()
    {
        return this.locMapping.get(Math.floorMod(this.locMappingNumber - 2, this.numLocMappings));
    }
        
    private Map<JButton, Locomotive> currentLocMapping()
    {
        return this.locMapping.get(this.locMappingNumber - 1);
    }
    
    /**
     * Same as currentLocMapping, but filters on the locomotives in the passed array
     * @param l
     * @return 
     */
    private Map<JButton, Locomotive> currentLocMapping(List<Locomotive> l)
    {
        Map<JButton, Locomotive> result = new HashMap<>();
        
        for (Map.Entry<JButton, Locomotive> entry : this.currentLocMapping().entrySet())
        {
            if (l.contains(entry.getValue()))
            {
                result.put(entry.getKey(), entry.getValue());
            }
        }
        
        return result;
    }
    
    private void displayCurrentButtonLoc(javax.swing.JButton b)
    {
        displayCurrentButtonLoc(b, false);
    }
    
    private void displayCurrentButtonLoc(javax.swing.JButton b, boolean showSelector)
    {
        javax.swing.SwingUtilities.invokeLater(() ->
        {
            if (this.currentButton != null)
            {
                this.currentButton.setEnabled(true);
                this.labelMapping.get(this.currentButton).setForeground(Color.black);
            }

            if (b != null)
            {
                this.currentButton = b;
                this.currentButtonlocMappingNumber = this.locMappingNumber;

                this.currentButton.setEnabled(false);

                Locomotive current = this.currentLocMapping().get(this.currentButton);

                if (current != null)
                {
                    this.activeLoc = this.model.getLocByName(current.getName());
                }
                else
                {
                    this.activeLoc = null;
                }

                this.labelMapping.get(this.currentButton).setForeground(Color.red);
            }

            this.lastLocMappingPainted = this.locMappingNumber;

            repaintLoc();  
            repaintMappings();
            
            // Show selector if no locomotive is assigned and clipboard is empty
            if (showSelector && this.activeLoc == null && this.copyTarget == null)
            {
                showLocSelector(true);
            }
        });
    }

    private void setLocSpeed(int speed)
    {
        if (this.activeLoc != null)
        {
            new Thread(() ->
            {
                this.activeLoc.setSpeed(speed);
            }).start();
        }
    }     
    
    private void stopLoc()
    {
        if (this.activeLoc != null)
        {
            new Thread(() ->
            {
                this.activeLoc.instantStop();
            }).start();
        }
    }
    
    private void backwardLoc()
    {
        if (this.activeLoc != null) // && this.activeLoc.goingForward())
        {
            new Thread(() ->
            {
                this.activeLoc.stop().setDirection(Locomotive.locDirection.DIR_BACKWARD);
                this.Forward.setSelected(false);
                this.Backward.setSelected(true);
            }).start();
        } 
    }
    
    private void forwardLoc()
    {
        if(this.activeLoc != null) // && this.activeLoc.goingBackward())
        {
            new Thread(() ->
            {
                this.activeLoc.stop().setDirection(Locomotive.locDirection.DIR_FORWARD);
                this.Forward.setSelected(true);
                this.Backward.setSelected(false);
            }).start();
        }
    }
    
    private void switchDirection()
    {
        if(this.activeLoc != null)
        {
             if (this.activeLoc.goingForward())
             {
                 backwardLoc();
             }
             else
             {
                 forwardLoc();
             }
        }  
    }
      
    private void go()
    {
        new Thread(() ->
        {
            this.model.go();
        }).start();
    }
    
    private void stop()
    {
        new Thread(() ->
        {
            this.model.stop();
        }).start();
    }
        
