    /**
     * Validates that a component's value is an integer
     * @param evt 
     * @param hex 
     */
    public static void validateInt(java.awt.event.KeyEvent evt, boolean hex)
    {
        JTextField field = (JTextField) evt.getSource();
        
        try
        {
            int addr = Integer.parseInt(field.getText());
            
            if (addr < 0)
            {
                field.setText(field.getText().replaceAll("[^0-9]", ""));    
            }
        }
        catch (Exception e)
        {            
            if (field.getText() != null)
            {
                String candidate = field.getText().replaceAll("[^0-9" + (hex ? "A-Fa-fx" : "") + "]", "");

                if (!candidate.equals(field.getText())) field.setText(candidate);
            }
        }
    }
    
    /**
     * Validates that a component's value is simple string
     * @param evt 
     */
    public static void validateLayoutName(java.awt.event.KeyEvent evt)
    {
        JTextField field = (JTextField) evt.getSource();
        
        if (field.getText() != null)
        {
            String candidate = field.getText().replaceAll("[^0-9a-zA-Z_\\. \\-]", "");

            if (!candidate.equals(field.getText())) field.setText(candidate);
        }
    }
    
    /**
     * Validates that a component's value is an integer
     * @param evt 
     * @param maxLength 
     */
    public static void limitLength(java.awt.event.KeyEvent evt, int maxLength)
    {
        JTextField field = (JTextField) evt.getSource();
        
        // Trim if needed
        if (field.getText() != null && field.getText().length() > maxLength)
        {
            field.setText(field.getText().substring(0, maxLength));
        }
    }
         
    public void editRoute(String routeName)
    {
        new Thread(()->
        {  
            if (routeName != null && this.model.getRoute(routeName) != null)
            {          
                {
                    Route currentRoute = this.model.getRoute(routeName);
                    
                    // Realised on the EDT.  Everything above - the model lookups, toCSV - belongs
                    // off it and stays off it, but constructing, packing and showing a JFrame is not
                    // thread safe, and the command-capture path then writes this window's document
                    // from the EDT while it is still being built on another thread.
                    final String title = I18n.f(
                        "route.ui.dialogEditRouteWithId",
                        routeName,
                        currentRoute.getId()
                    );

                    if (refuseWhileEditorOpen()) return;

                    javax.swing.SwingUtilities.invokeLater(() ->
                    {
            // Checked on the EDT, immediately before constructing, so the two cannot be separated.
            //
            // The check used to run out here on the worker while the construction was posted to the
            // event thread, which left a window between them: two clicks in quick succession - a
            // double-click on the button is enough - both saw a null field, both posted, and two
            // editors opened.  The field then held whichever was assigned last, and captured commands
            // went to that one while the user was typing in the other.
            //
            // The model reads above stay off the EDT.  Only the decision moves.
                        if (routeEditor != null && routeEditor.isVisible())
                        {
                            JOptionPane.showMessageDialog(
                                this,
                                I18n.t("route.ui.errorOnlyOneRouteEditorAllowed")
                            );

                            routeEditor.requestFocus();
                            routeEditor.toFront();

                            return;
                        }

                        // The route itself, rather than its name to look up again: this window is
                        // handed what it is to show, which is what makes its read-only behaviour
                        // testable without a control station on the network.
                        routeEditor = new RouteEditorFrame(this, routeName, currentRoute);

                        // Not over a locked route's own title.  A route from the Central Station
                        // opens with every control greyed and its title is the only thing that says
                        // why; overwriting it with the ordinary edit-route title left a window full
                        // of dead controls and no explanation.
                        if (!routeEditor.isLocked()) routeEditor.setTitle(title);
                        routeEditor.setVisible(true);
                    });
                }
            }
        }).start();
    }
    
