    public void deleteTimetableEntry(MouseEvent evt)
    {
        try
        {
            if (this.isAutonomyBusy())
            {
                JOptionPane.showMessageDialog(this, I18n.t("autolayout.ui.errorWaitForActiveLocomotivesToStop"));
                return;
            }
            
            int index = this.getTimetableIndexAtCursor(evt);
            
            if (index >= 0)
            {
                int dialogResult = JOptionPane.showOptionDialog(
                    this,
                    I18n.f(
                        "timetable.ui.confirmRemoveEntryContinue",
                        index,
                        this.getTimetableEntryAtCursor(evt)
                    ),
                    I18n.t("timetable.ui.dialogConfirmDeletion"),
                    JOptionPane.YES_NO_OPTION,
                    JOptionPane.PLAIN_MESSAGE,
                    null,
                    YES_NO_OPTS,
                    // UXR-B5: index 0 is Yes - this said "No" and pre-selected the delete. Enter on
                    // this confirmation deleted the timetable entry with no undo, one keypress rather
                    // than the two the comment believed it was requiring.
                    YES_NO_OPTS[1] // default selection = "No"
                );

                // Anything but Yes.
                if (dialogResult != JOptionPane.YES_OPTION) return;
         
                this.model.getAutoLayout().getTimetable().remove(index);
                this.repaintTimetable();
            }
        }
        catch (Exception e)
        {
            this.model.log(e);

            JOptionPane.showMessageDialog(this, I18n.f("error.generic", e.getMessage()));
        }    
    }
    
    public void updateTimetableDelay(MouseEvent evt)
    {
        try
        {
            if (this.isAutonomyBusy())
            {
                JOptionPane.showMessageDialog(this, I18n.t("autolayout.ui.errorWaitForActiveLocomotivesToStop"));
                return;
            }
            
            TimetablePath ttp = (TimetablePath) getTimetableEntryAtCursor(evt);

            if (ttp != null)
            {
                String input = JOptionPane.showInputDialog(
                    this,
                    I18n.t("timetable.ui.enterDelaySecondsBeforeRouteExecutes"),
                    (int) (ttp.getSecondsToNext() / 1000.0)
                );

                if (input != null)
                {
                    ttp.setSecondsToNext(Long.parseLong(input) * 1000);
                    this.repaintTimetable();
                } 
            }
        }
        catch (Exception e)
        {
            this.model.log(e);

            JOptionPane.showMessageDialog(this, I18n.f("error.generic", e.getMessage()));
        }
    }
    
    /**
     * Restarts timetable execution from the top
     */
    public void restartTimetable()
    {
        javax.swing.SwingUtilities.invokeLater(() -> 
        {
            if (this.isAutonomyBusy())
            {
                JOptionPane.showMessageDialog(this, I18n.t("autolayout.ui.errorWaitForActiveLocomotivesToStop"));
                return;
            }
            
            // Check if a reset will do anything
            if (this.getModel().getAutoLayout().getUnfinishedTimetablePathIndex() == 0
                && !this.getModel().getAutoLayout().getTimetable().isEmpty()
                && this.getModel().getAutoLayout().getTimetable().get(0).getExecutionTime() == 0
            )
            {
                JOptionPane.showMessageDialog(
                    this,
                    I18n.t("timetable.ui.infoTimetableAlreadyReset")
                );
                return;
            }

            int dialogResult = JOptionPane.showOptionDialog(
                this,
                I18n.t("timetable.ui.confirmRestartMarkEntriesUnvisited"),
                I18n.t("timetable.ui.dialogConfirmRestart"),
                JOptionPane.YES_NO_OPTION,
                JOptionPane.PLAIN_MESSAGE,
                null,
                YES_NO_OPTS,
                YES_NO_OPTS[0]
            );

            // Anything but Yes.
            if (dialogResult != JOptionPane.YES_OPTION) return;

            this.getModel().getAutoLayout().resetTimetable();
            this.repaintTimetable();
        });
    }
        
    public void setFunctionIcon(Locomotive l, JButton source, MouseEvent evt)
    {
        Window sourceWindow = evt != null ? SwingUtilities.getWindowAncestor((Component) evt.getSource()) : this;
        
        javax.swing.SwingUtilities.invokeLater(() -> 
        {    
            LocomotiveFunctionAssign edit = new LocomotiveFunctionAssign(l, this, 0, false);
            // Select the locomotive
            if (source != null)
            {
                source.doClick();
            }
            
            // Create a custom dialog without buttons
            JDialog dialog = new JDialog(sourceWindow, 
                                         I18n.f("loc.ui.dialogEditLocomotiveFunctions", l.getName()), 
                                         Dialog.ModalityType.APPLICATION_MODAL);

            // OB-124.
            applyWindowIcon(dialog);
            dialog.getContentPane().add(edit);
            dialog.pack();
            dialog.setLocationRelativeTo(sourceWindow);
            dialog.setDefaultCloseOperation(JDialog.DISPOSE_ON_CLOSE);
            dialog.setResizable(false);
            
            // Add Escape key binding to close the dialog
            KeyStroke escapeKeyStroke = KeyStroke.getKeyStroke(KeyEvent.VK_ESCAPE, 0);
            dialog.getRootPane().getInputMap(JComponent.WHEN_IN_FOCUSED_WINDOW)
                  .put(escapeKeyStroke, "ESCAPE");
            dialog.getRootPane().getActionMap()
                  .put("ESCAPE", new AbstractAction() {
                      @Override
                      public void actionPerformed(ActionEvent e) {
                          dialog.dispose();
                      }
                  });
            
            // UXR-B4: setVisible(true) on an APPLICATION_MODAL dialog does not return until the
            // dialog is dismissed, so a call placed after it - as this one used to be - runs on a
            // component whose window is already gone and focuses nothing. Queued instead: an
            // invokeLater posted before a modal show enters Swing's nested event loop for that
            // dialog runs from inside that loop, once the dialog is actually on screen, rather than
            // after it, which is what the caller wanted a focused field for in the first place.
            javax.swing.SwingUtilities.invokeLater(edit::focusFno);

            dialog.setVisible(true);
        });
    }
    
    /**
     * The blue this application picks things out in.
     *
     * FlatLightLaf's accent, written down rather than asked of UIManager: the key that holds it has
     * changed name between FlatLaf releases, and a badge that silently comes back null and paints
     * nothing is worse than one that is a shade off after an upgrade.
     */
    private static final Color PAGE_BADGE_BLUE = new Color(0x26, 0x75, 0xBF);

    /**
     * Draws the keyboard page number in the corner of the locomotive tab icon.
     *
     * Adam, 2026-08-27: "show the page number instead in a circle to the upper right of the
     * locomotive, in blue bg color matching the theme and white font.  manage double digits.  hide it
     * if the page number is 1."
     *
     * **Page one wears nothing**, which is the point of it: most people never leave page one, and a
     * badge that is always there says nothing. It appears when there is something to say.
     *
     * **More than one digit stretches the circle into a capsule** rather than shrinking the type. At
     * this size the difference between a ten-point digit and an eight-point one is the difference
     * between reading it and guessing, so the shape gives way instead of the type.
     *
     * **Two digits is the most this has to draw**, and it is a cap rather than an assumption: Adam
     * asked for a ceiling of fifty pages on 2026-08-27 and `MAX_LOC_MAPPINGS` enforces it. An earlier
     * version of this comment assumed two digits on the strength of the default being ten, which was
     * false at the time - the assumption is only safe now because something checks it.
     *
     * It is not written to NEED that, though. Checked by rendering before the cap existed: 100 and 999
     * both fit and stay legible, the capsule growing to about two thirds of the icon. So a state saved
     * before today - which is not capped, see `addLocMappingPage` - still draws its page number.
     *
     * **Centred on the icon**, which is where it ended up after being tried in the corner. It covers
     * part of the locomotive either way - the drawing fills its square - so the choice is only about
     * which part, and the middle is where the eye already is.
     *
     * The badge is drawn onto a COPY. The tab icon is a static shared between every use of it, and
     * painting the number onto it would put page 4's badge on the locomotive panel and everywhere else
     * the same image is drawn.
     *
     * This replaces a merge of two text layers - white with a black shadow one pixel down and right -
     * centred over the whole icon. That is why the locomotive was drawn solid through the middle and
     * why its cab window was moved out of the way: white text on the empty part of an icon is white
     * text on the tab strip. None of that constraint survives this, and the drawing is free of it.
     *
     * @param icon the tab icon to badge, not modified
     * @param page the keyboard page number
     * @return a new image, or the one passed in when there is nothing to show
     */
    private BufferedImage withPageBadge(BufferedImage icon, int page)
    {
        if (icon == null || page <= 1) return icon;

        String text = Integer.toString(page);

        BufferedImage out = new BufferedImage(icon.getWidth(), icon.getHeight(),
            BufferedImage.TYPE_INT_ARGB);

        java.awt.Graphics2D g = out.createGraphics();

        g.setRenderingHint(java.awt.RenderingHints.KEY_ANTIALIASING,
            java.awt.RenderingHints.VALUE_ANTIALIAS_ON);
        g.setRenderingHint(java.awt.RenderingHints.KEY_TEXT_ANTIALIASING,
            java.awt.RenderingHints.VALUE_TEXT_ANTIALIAS_ON);

        g.drawImage(icon, 0, 0, null);

        g.setFont(new Font("Segoe UI", Font.BOLD, 10));

        // The digits' INK, not their font metrics.
        //
        // Centring on `stringWidth` and `getHeight()` put them a pixel low every time, and a pixel left
        // on one digit and a pixel right on two - measured, not guessed. Both are the usual causes:
        // getHeight() includes leading, which is space below the descent that no digit occupies, and
        // stringWidth includes the side bearings, which differ between "2" and "10".
        //
        // The visual bounds are what is actually drawn, so centring on them centres what the eye sees.
        java.awt.font.GlyphVector glyphs =
            g.getFont().createGlyphVector(g.getFontRenderContext(), text);

        java.awt.geom.Rectangle2D ink = glyphs.getVisualBounds();

        int tall = 13;
        int wide = Math.max(tall, (int) Math.ceil(ink.getWidth()) + 7);

        // CENTRED over the locomotive (Adam, 2026-08-27, having seen it in the corner).
        //
        // Clamped at zero for the same reason it was clamped in the corner: an icon narrower than its
        // own badge would otherwise start off the left edge.
        int x = Math.max(0, (out.getWidth() - wide) / 2);
        int y = Math.max(0, (out.getHeight() - tall) / 2);

        g.setColor(PAGE_BADGE_BLUE);
        g.fillRoundRect(x, y, wide, tall, tall, tall);

        g.setColor(Color.WHITE);
        g.drawString(text,
            (float) (x + (wide - ink.getWidth()) / 2 - ink.getX()),
            (float) (y + (tall - ink.getHeight()) / 2 - ink.getY()));

        g.dispose();

        return out;
    }

    /**
     * The hover crop mark drawn over locIcon (FR-032); null until the window is built.
     *
     * DECLARED HERE, not in the generated variables block, and that is the whole point of this
     * comment. It sat in that block for months and disappeared twice on 2026-08-28, taking the build
     * with it - because `cropOverlay` is not a form component. It is created below by hand and
     * TrainControlUI.form has never heard of it, so every time NetBeans regenerates that block from
     * the form - which happens whenever the designer is used for anything, a label colour included -
     * the field is simply not written back out.
     *
     * Nothing removed it. It was in a place that gets rewritten from a file that does not mention it.
     */
    private javax.swing.JLabel cropOverlay;

    /**
     * Puts the hover crop mark on the big locomotive picture (FR-032).
     *
     * Adam: "can you add a hover crop icon to the upper-right of the big locomotive image when
     * hovered?"
     *
     * Built here rather than in the designer, which owns `locIcon` and whose generated block is not
     * ours to edit. A JLabel has no layout of its own, so it is given one - the label goes on painting
     * its picture underneath either way, and children are drawn over it.
     *
     * **Only when there is something to re-crop.** The mark is hidden when the locomotive has no local
     * icon at all, because there would be nothing for it to open; the right-click that sets one in the
     * first place is unchanged and is still the way in.
     *
     * The hover test is `getMousePosition(true)` and the `true` is the whole of it: moving the pointer
     * onto a CHILD fires mouseExited on its parent, so the obvious version hides the mark at the
     * moment the user reaches for it, and it flickers instead of being clickable.
     */
    private void buildCropOverlay()
    {
        cropOverlay = new JLabel(new CropMark());

        cropOverlay.setToolTipText(I18n.t("loc.ui.tooltip.recrop"));
        cropOverlay.setCursor(new java.awt.Cursor(java.awt.Cursor.HAND_CURSOR));
        cropOverlay.setVisible(false);
        cropOverlay.setOpaque(false);

        cropOverlay.addMouseListener(new java.awt.event.MouseAdapter()
        {
            @Override
            public void mouseReleased(java.awt.event.MouseEvent evt)
            {
                if (activeLoc == null) return;

                // LEFT re-crops; RIGHT does what the picture underneath does (C7, then its own
                // review).
                //
                // The mark has a listener of its own, so Swing targets IT and never passes the event
                // on to locIcon - `locIconMouseReleased`, which opens "set icon", simply does not run
                // over these fifteen pixels. The first version of this guard returned on a right click
                // and stopped there, which removed the wrong behaviour without putting the right one
                // back: a fifteen-pixel hole where right-clicking the locomotive did nothing at all.
                //
                // DOC-B10: the hole moves with the mark rather than closing on its own. It sat in the
                // MIDDLE of the picture for one round (2026-08-27) - exactly where a person aims when
                // they right-click it - and has since been moved to the upper right corner, below.
                // Wherever it sits, right-clicking those fifteen pixels lands on the mark, not on
                // locIcon underneath, which is why this passthrough still matters regardless of where
                // "there" currently is.
                if (SwingUtilities.isLeftMouseButton(evt))
                {
                    recropLocIcon(activeLoc, TrainControlUI.this);
                }
                else if (SwingUtilities.isRightMouseButton(evt))
                {
                    setLocIcon(activeLoc);
                }
            }
        });

        // UPPER RIGHT (Adam, 2026-08-27, having seen it centred).
        //
        // It does overlap the picture - a cropped icon is exactly LOC_ICON_WIDTH by LOC_ICON_HEIGHT,
        // 296 by 114 in a 296 by 116 label, so every position inside is over the photograph. Centred
        // was the answer to that; in the corner is what he wants having looked at both, and a corner
        // takes less of the picture than the middle does whatever it overlaps.
        //
        // Hard into the corner, with no gap: the label has a pixel of slack top and bottom and none at
        // the sides, so any inset here spends picture rather than margin.
        JPanel corner = new JPanel(new java.awt.FlowLayout(java.awt.FlowLayout.RIGHT, 0, 0));

        corner.setOpaque(false);
        corner.add(cropOverlay);

        locIcon.setLayout(new java.awt.BorderLayout());
        locIcon.add(corner, java.awt.BorderLayout.NORTH);

        java.awt.event.MouseAdapter hover = new java.awt.event.MouseAdapter()
        {
            @Override
            public void mouseEntered(java.awt.event.MouseEvent evt)
            {
                showCropOverlay();
            }

            @Override
            public void mouseExited(java.awt.event.MouseEvent evt)
            {
                // Still inside, counting children: entering the mark itself is an exit from the label.
                if (locIcon.getMousePosition(true) == null) cropOverlay.setVisible(false);
            }
        };

        locIcon.addMouseListener(hover);
        cropOverlay.addMouseListener(hover);

        // A HAND, so the picture looks like something you can act on (Adam, 2026-09-01).
        //
        // "change the mouse pointer on hover to indicate editability / add a tooltip."  The tooltip was
        // already there and says what to do - "Right-click to change icon" - but a tooltip is only read
        // by somebody who already suspects there is something to read.  The pointer is what raises the
        // suspicion, and it costs nothing to be right about: right-clicking here really does open the
        // icon chooser, on every locomotive, with or without a picture of its own.
        //
        // Set here rather than in the form, because the form's block is regenerated and a line added
        // inside it does not survive.
        locIcon.setCursor(java.awt.Cursor.getPredefinedCursor(java.awt.Cursor.HAND_CURSOR));
        cropOverlay.setCursor(java.awt.Cursor.getPredefinedCursor(java.awt.Cursor.HAND_CURSOR));
    }

    /**
     * Shows the crop mark, if this locomotive has an icon that can be re-cropped.
     */
    private void showCropOverlay()
    {
        if (cropOverlay == null) return;

        // Only while the pointer is actually over the picture, and only when there is an icon of our
        // own to re-crop.  Called from the repaint path as well as from hover, so it cannot assume it
        // is being called because the pointer just arrived.
        cropOverlay.setVisible(activeLoc != null && activeLoc.getLocalImageURL() != null
            && locIcon.getMousePosition(true) != null);
    }

    /**
     * The crop mark itself, drawn rather than loaded.
     *
     * Two overlapping right angles, which is what every photo tool uses for this and what nothing else
     * in the application looks like. Drawn because it is eleven pixels of two lines: a PNG would want
     * a size, a folder, a name, and a test that it is still there.
     *
     * A white line is laid under the dark one so it reads on a photograph of any colour, which is the
     * same problem the running-train marker on the diagram has and the same answer.
     */
    private static final class CropMark implements javax.swing.Icon
    {
        private static final int SIZE = 15;

        private static final int INSET = 4;

        @Override
        public int getIconWidth()
        {
            return SIZE;
        }

        @Override
        public int getIconHeight()
        {
            return SIZE;
        }

        @Override
        public void paintIcon(java.awt.Component host, java.awt.Graphics g, int x, int y)
        {
            java.awt.Graphics2D g2 = (java.awt.Graphics2D) g.create();

            g2.setRenderingHint(java.awt.RenderingHints.KEY_ANTIALIASING,
                java.awt.RenderingHints.VALUE_ANTIALIAS_ON);

            for (int pass = 0; pass < 2; pass++)
            {
                g2.setColor(pass == 0 ? new java.awt.Color(255, 255, 255, 200)
                    : new java.awt.Color(51, 51, 51));
                g2.setStroke(new java.awt.BasicStroke(pass == 0 ? 3.4f : 1.8f,
                    java.awt.BasicStroke.CAP_ROUND, java.awt.BasicStroke.JOIN_ROUND));

                int near = INSET;
                int far = SIZE - INSET;

                // The top-left angle, and the bottom-right one, each overshooting the other's corner -
                // which is what makes the pair read as crop marks rather than as a box.
                g2.drawLine(x + near, y + 1, x + near, y + far);
                g2.drawLine(x + 1, y + near, x + far, y + near);

                g2.drawLine(x + far, y + near, x + far, y + SIZE - 1);
                g2.drawLine(x + near, y + far, x + SIZE - 1, y + far);
            }

            g2.dispose();
        }
    }

    /**
     * What is appended to a crop's own name to make the name of the note beside it (FR-032).
     *
     * Deliberately not a picture extension: `Util.isLocIconFile` and the file chooser's filter both
     * work by extension, and a note that looked like an image would turn up as one.
     */
    private static final String CROP_SOURCE_SUFFIX = ".source";

    /**
     * What the second line of a crop's note starts with, when it has one (OB-125).
     *
     * Prefixed rather than positional so that a note whose second line is something else - an older
     * format, a stray newline, a file half-written by something that died - is ignored rather than
     * parsed into a view.
     */
    private static final String CROP_VIEW_PREFIX = "view=";

    /**
     * Asks how long a train is, and remembers the answer (FR-047).
     *
     * Adam: "allow the train length to be set both from the right click locomotive menu on the key
     * mappings, and the right click menu in the locomotive database editor."  Two doors, and this is
     * the only implementation - the menus differ in where they are opened from and in nothing else.
     *
     * The number matters because autonomy refuses a platform to a train too long for it. A train with
     * no length is never refused anything, which is why FR-046 warns about one; this is the other half
     * of that, somewhere to set it without opening the autonomy editor.
     *
     * Zero means "not set", the way it does everywhere else this number is used - the station maximum
     * uses the same convention, and a train of length zero and a train of unknown length are the same
     * thing to the railway.
     *
     * @param l the locomotive
     * @param evt where the click was, so the dialog opens near it, or null
     */
    public void promptTrainLength(Locomotive l, MouseEvent evt)
    {
        if (l == null) return;

        Integer current = l.getTrainLength();

        // THE SAME LIST THE AUTONOMY EDITOR OFFERS: 0 to 20 (Adam).
        //
        // It was a text box, and a text box can hold 400, or "twelve", or a minus sign - so it needed
        // parsing, a range check and two error dialogs to say what a list simply cannot express. The
        // Edit Locomotive view in the autonomy editor has always used this dropdown for the same
        // field, and two places that set one number should not disagree about what a legal value is.
        String[] lengths = new String[ROUTE_TRAIN_LENGTH_MAX + 1];

        for (int i = 0; i < lengths.length; i++) lengths[i] = String.valueOf(i);

        int start = current == null || current < 0 || current > ROUTE_TRAIN_LENGTH_MAX ? 0 : current;

        String answer = (String) JOptionPane.showInputDialog(
            evt == null ? this : evt.getComponent(),
            I18n.t("autolayout.ui.trainLength"),
            l.getName(),
            JOptionPane.PLAIN_MESSAGE,
            null, lengths, lengths[start]);

        // Cancel, which is not the same as choosing zero - and zero is a real choice here, being how
        // this field says "not set".
        if (answer == null) return;

        l.setTrainLength(Integer.parseInt(answer));

        this.model.logf("autolayout.infoSetTrainLength", answer, l.getName());

        // The findings follow the number: FR-046 warns about a train with no length, and that warning
        // has to go when the length arrives rather than at the next rebuild.
        refreshAutonomyPrompt();
    }

    /**
     * The longest train the length dropdowns offer.
     *
     * Twenty, which is what the autonomy editor's Edit Locomotive view has always listed. Named rather
     * than written twice, so the two dropdowns cannot come to disagree.
     */
    public static final int ROUTE_TRAIN_LENGTH_MAX = 20;

    /**
     * Removes the local icon override, so the Central Station's own picture is shown again.
     * @param l the locomotive
     */
    public void clearLocIcon(Locomotive l)
    {
        javax.swing.SwingUtilities.invokeLater(() ->
        {
            // FR-022.  A crop of our own is only ever referenced by the locomotive it was made for,
            // so clearing that reference is the moment it becomes unreachable.  Without this the
            // folder would grow by one file for every icon the user ever set and never shrink, and
            // there is nothing in the interface that would let them tidy it.  Only files inside our
            // own folder qualify - the user's original picture is never ours to delete.
            String superseded = l.getLocalImageURL();

            l.setLocalImageURL(null);

            if (Util.isLocIconFile(superseded))
            {
                deleteLocIconFile(superseded);
            }

            this.syncWithCS2();
            this.repaintLoc(true, null);
            this.repaintMappings(Collections.singletonList(l), true);
            this.selector.refreshLocSelectorList();
        });
    }
    
    public void setLocIcon(Locomotive l)
    {
        setLocIcon(l, null);
    }
    
    /**
     * Allows a local image to be set for a locomotive
     * @param l 
     * @param evt
     */
    public void setLocIcon(Locomotive l, MouseEvent evt)
    {
        Component source = evt != null ? (Component) evt.getSource() : this;
        
        javax.swing.SwingUtilities.invokeLater(() -> 
        {
            String currentPath = null;

            if (l.getLocalImageURL() != null)
            {
                // Through a URI, because that is what the value IS (UI review, C4).
                //
                // `new File(String)` on a "file:/..." URI produces a path that never exists, so
                // currentPath was always null and the chooser never opened where the current icon
                // lives - a silent no-op since the day it was written. FR-022's own new code got this
                // right in isLocIconFile and deleteLocIconFile; this line is its twin, one method away.
                //
                // And it must NOT open in tc_loc_icons, which is where a cropped icon lives: that is
                // the application's own folder, not somewhere the operator keeps photographs. So the
                // chooser starts where the current icon is only when that is somewhere else.
                File currentIcon = fileOf(l.getLocalImageURL());

                if (currentIcon != null && currentIcon.exists()
                    && !org.traincontrol.util.Util.isLocIconFile(l.getLocalImageURL()))
                {
                    currentPath = currentIcon.getParent();
                }

                this.model.logf(
                    "loc.ui.infoCurrentIconForLocomotiveIsUrl",
                    l.getName(),
                    l.getLocalImageURL()
                );
            }
            
            JFileChooser fc = new JFileChooser(
                currentPath != null ? currentPath : prefs.get(LAST_USED_ICON_FOLDER, new File(".").getAbsolutePath())
            );

            fc.setFileSelectionMode(JFileChooser.FILES_ONLY);
            FileFilter filter = new FileNameExtensionFilter("JPEG, PNG, GIF, BMP " + I18n.t("ui.images"), "jpg", "png", "gif", "jpeg", "jpe", "bmp");
            fc.setFileFilter(filter);

            fc.setAcceptAllFileFilterUsed(false);

            // FR-022.  The offer lives in the chooser, beside the files, because that is where the
            // user is when the question "will the whole of this picture fit?" occurs to them.  A
            // menu item alongside "Set Local Locomotive Icon" would have been a second way to start
            // the same job, and two entrances to one thing is how a menu stops being readable.
            final JCheckBox crop = new JCheckBox(I18n.t("loc.ui.cropCheckbox"),
                prefs.getBoolean(CROP_LOC_ICON_PREF, false));

            crop.setToolTipText(I18n.t("loc.ui.tooltip.cropCheckbox"));

            // UNDER the file name, not in the accessory panel (Adam: "is there a way to put the
            // checkbox in a more organic place?").
            //
            // setAccessory hangs a component off the right-hand side of the chooser, beside the file
            // list - which is where a preview pane belongs, and reads as something bolted on when it
            // holds one tick box. Along the bottom of the chooser is where a file dialog's options
            // live everywhere else.
            //
            // **SOUTH, and the constraint is the whole of it.** A JFileChooser is laid out with a
            // BorderLayout whose CENTER holds the entire browser - the places list, the file list,
            // the name field and the buttons, all of it. `fc.add(row)` with no constraint means
            // CENTER, so the tick box REPLACED the browser: the dialog came up with the shortcuts
            // down the side, one checkbox, and nothing else.
            //
            // I wrote that first, from a guess about the layout being vertical - which is what the
            // comment here used to claim. Rendering the chooser to a PNG showed it in a second; the
            // guess had survived a compile and a commit message.
            //
            // NORTH, SOUTH, EAST and WEST are all free, so this displaces nothing.
            JPanel row = new JPanel(new java.awt.FlowLayout(java.awt.FlowLayout.LEFT, 0, 0));
            row.setBorder(BorderFactory.createEmptyBorder(0, 2, 4, 2));
            row.add(crop);

            fc.add(row, java.awt.BorderLayout.SOUTH);

            int i = fc.showOpenDialog(source);

            if (i == JFileChooser.APPROVE_OPTION)
            {
                File f = fc.getSelectedFile();

                prefs.putBoolean(CROP_LOC_ICON_PREF, crop.isSelected());

                // The file the user picked, unless cropping produced a file of our own.  Assigned
                // before the crop is attempted so that every way the crop can fail - unreadable
                // picture, cancelled dialog, unwritable folder - lands on exactly the behaviour this
                // method had before FR-022 rather than on no icon at all.
                String chosenURL = Paths.get(f.getAbsolutePath()).toUri().toString();

                // READABLE AT ALL, whether or not it is going to be cropped.
                //
                // The guard for this used to live inside the branch below, so it only ran when Crop
                // was ticked - while the TODO at the foot of this method, which is this same bug
                // written down, sits on the path where it is not (validator, 2026-08-28). Untick Crop,
                // pick a CMYK JPEG or a `.png` that is really something else - both get past the
                // extension filter - and the locomotive is pointed at a file that renders as nothing
                // and the crop it had is deleted on the way.
                //
                // Costs a decode of a picture that is about to be decoded again by the crop dialog or
                // by the icon itself. That is a one-off on a file the user just picked by hand.
                if (!pictureCanBeRead(f, source)) return;

                if (crop.isSelected())
                {
                    // Cancel is not a failure, and treating it as one was destructive (LD-6).
                    //
                    // cropLocIcon returned null for both "the user pressed Cancel" and "the picture
                    // could not be read", and the line below then fell back to the UNCROPPED file -
                    // so pressing Cancel in the crop dialog set the full photograph as the icon and
                    // deleted the crop that was there before. Escape and the window's close box
                    // landed in the same place.
                    //
                    // The dialog's own javadoc already said null meant "leave everything exactly as
                    // it was, not a failure"; the two contracts were written the same day and the
                    // code followed the wrong one.
                    // Two answers, not one: was it cancelled, and was the picture unreadable.
                    boolean[] cancelled = {false, false};

                    String cropped = cropLocIcon(source, l, f, cancelled, null);

                    // Nothing is assigned and nothing is deleted: the locomotive keeps the icon it
                    // had, which is what cancelling a dialog means.
                    if (cancelled[0]) return;

                    // Nor when the picture could not be read at all.
                    //
                    // The fallback below - use the file the user picked, uncropped - is right when the
                    // picture is good and only the crop failed. Here it would point the locomotive at
                    // a file that renders as nothing AND delete the crop it had, which is the state a
                    // reviewer found. The sibling `recropLocIcon` has always refused this case.
                    if (cancelled[1]) return;

                    if (cropped != null) chosenURL = cropped;
                }

                // The crop this icon is replacing, if the icon it is replacing was one of ours.  Read
                // BEFORE the assignment and deleted after it, so a failure in between cannot leave
                // the locomotive pointing at a file that has been removed.
                String superseded = l.getLocalImageURL();

                l.setLocalImageURL(chosenURL);
                prefs.put(LAST_USED_ICON_FOLDER, f.getParent());

                if (!chosenURL.equals(superseded) && Util.isLocIconFile(superseded))
                {
                    deleteLocIconFile(superseded);
                }

                this.repaintLoc(true, null);
                this.repaintMappings(Collections.singletonList(l), true);
                this.selector.refreshLocSelectorList();

                // The note that stood here - clear the icon setting if the load failed - is done, and
                // is deleted rather than quoted so no marker is left behind. Nothing unreadable
                // reaches this point on either branch, so there is no failed load to clear up after.
            }
        });
    }

    /**
     * Whether a picture the user picked can actually be displayed, complaining if it cannot.
     *
     * The file chooser filters on the NAME. A `.png` that is really something else, a CMYK JPEG, a
     * HEIC renamed, a cloud-backed file that is not on this machine - all get past it, and every one
     * of them ends as a locomotive pointing at a file that renders as nothing.
     *
     * Asked before anything is assigned or deleted, because the deletion is the part that cannot be
     * undone: the crop being replaced is a file this application made and the user cannot get back.
     *
     * @param chosen the picture the user picked, opened for reading and nothing else
     * @param parent the component to complain on
     * @return whether it read as an image
     */
    private boolean pictureCanBeRead(File chosen, Component parent)
    {
        try
        {
            // ImageIO answers null rather than throwing for a file no reader claims, so both.
            if (ImageIO.read(chosen) != null) return true;
        }
        catch (IOException | RuntimeException failed)
        {
            this.model.log(failed);
        }

        this.model.logf("ui.errorFailedToLoadImage", chosen.getAbsolutePath());

        JOptionPane.showMessageDialog(parent,
            I18n.f("loc.ui.errorPictureCouldNotBeRead", chosen.getName()));

        return false;
    }

    /**
     * FR-022 - runs the crop dialog over a picture the user has just picked, and stores what comes
     * back as a locomotive icon of our own.
     *
     * The user's file is opened for READING and nothing else.  Adam picks these out of his own photo
     * folders; a program that writes into them, or over the photograph it was shown, has done
     * something he did not ask for and cannot undo.  The crop is a new picture and goes in the
     * application's own folder.
     *
     * PNG regardless of what the source was.  A crop of a transparent icon - which is what the
     * Central Station's own locomotive pictures are - would have its transparency flattened to black
     * by JPEG, and the icons are drawn straight onto a coloured button where that is unmissable.
     *
     * @param parent the component the dialog should centre on
     * @param l the locomotive the icon is for; its name is used to make the file recognisable
     * @param chosen the picture the user picked, never written to
     * @param cancelled set to true when the user dismissed the crop dialog, which is NOT a failure:
     *                  the caller must then change nothing at all. Collapsing the two used to set the
     *                  uncropped photograph as the icon and delete the crop it replaced (LD-6)
     * @return the URL of the cropped icon, or null if there is nothing to use - the user cancelled,
     *         the picture could not be read, or the folder could not be written - in which case the
     *         caller must fall back to the uncropped original
     */
    private String cropLocIcon(Component parent, Locomotive l, File chosen, boolean[] cancelled,
        double[] opening)
    {
        // One array, in and out: what to open on, and afterwards what the user settled on (OB-125).
        // Allocated here when the caller has nothing to open on, because the note still wants
        // recording either way.
        double[] view = opening != null ? opening
            : new double[] { Double.NaN, Double.NaN, Double.NaN, Double.NaN, Double.NaN };

        BufferedImage picture;

        try
        {
            picture = ImageIO.read(chosen);
        }
        catch (IOException | RuntimeException e)
        {
            picture = null;
        }

        if (picture == null)
        {
            // ImageIO returns null rather than throwing for a file no reader claims - a .png that is
            // really something else, which is common enough among pictures collected off the web.
            this.model.logf("ui.errorFailedToLoadImage", chosen.getAbsolutePath());

            // AND SAID OUT LOUD, because the caller must not fall back to this file.
            //
            // Falling back to the picture the user chose is right when the picture is good and only
            // the crop failed. It is the worst of both when the picture cannot be read: the locomotive
            // is pointed at a file that renders as nothing, and the crop it had is deleted on the way.
            if (cancelled != null) cancelled[1] = true;

            JOptionPane.showMessageDialog(parent,
                I18n.f("loc.ui.errorPictureCouldNotBeRead", chosen.getName()));

            return null;
        }

        BufferedImage cropped = LocIconCropDialog.crop(parent, picture, LOC_ICON_WIDTH,
            LOC_ICON_HEIGHT, view);

        // The dialog returns null only when the user said no - Cancel, Escape, or the close box. Its
        // own javadoc calls that "leave everything exactly as it was, not a failure", and the caller
        // needs to be able to tell it apart from the failures above, which DO fall back to the file
        // the user picked.
        if (cropped == null)
        {
            if (cancelled != null) cancelled[0] = true;

            return null;
        }

        // A fresh name every time, never the same file overwritten.  getLocImage caches by URL, and
        // the cache has no way to know a file behind a URL it has already read has changed - reusing
        // the name would show the OLD crop until the application was restarted, which reads as the
        // crop dialog having done nothing.  The superseded file is deleted by the caller, so this
        // accumulates one file per locomotive rather than one per attempt.
        String name = Util.sanitizeFilename(l.getName()) + "_" + System.currentTimeMillis() + ".png";

        File target = Util.getLocIconFile(name);

        if (target == null)
        {
            this.model.logf("loc.ui.errorCropCouldNotBeSaved", Util.LOC_ICON_FOLDER);

            return null;
        }

        try
        {
            // The RETURN VALUE, which ImageIO answers false with rather than throwing when no writer
            // claims the format. Thrown away here, a zero-byte file was moved into place, reported as
            // a success, and the crop it replaced deleted on the strength of it. DiagramExport checks
            // the same call.
            Util.writeAtomically(target, out ->
            {
                if (!ImageIO.write(cropped, "png", out))
                {
                    throw new IOException("no writer claimed PNG for " + target.getAbsolutePath());
                }
            });
        }
        catch (IOException | RuntimeException e)
        {
            this.model.logf("loc.ui.errorCropCouldNotBeSaved", target.getAbsolutePath());
            this.model.log(e);

            return null;
        }

        // Not when the picture cropped was itself one of our crops (validator).
        //
        // A crop with no note - anything made before FR-032 - re-crops from the crop itself, and this
        // line would then write a note naming that crop, which the caller deletes three lines later.
        // The note would name a file that no longer exists, be believed by the next re-crop, and be
        // carried forward for ever. A note that is wrong is worse than no note: no note degrades to
        // "crop the crop", which is correct, and says so.
        if (!Util.isLocIconFile(chosen.toPath().toUri().toString()))
        {
            rememberCropSource(target, chosen, view);
        }

        return target.toPath().toUri().toString();
    }

    /**
     * Notes, beside a crop, which picture it was cut out of (FR-032).
     *
     * Re-cropping needs the ORIGINAL. Cropping a crop can only ever go tighter - the picture outside
     * the last crop is gone - so "crop/pan without reselecting the source" would have meant panning in
     * one direction only, which is not panning.
     *
     * A sidecar file rather than anywhere cleverer. The alternatives were all worse: a second field on
     * Locomotive means the model, its copy constructor and its serialisation for something only the
     * interface cares about; a preference keyed by locomotive name breaks the first time one is
     * renamed, which this application has a whole class of repairs for already; and PNG metadata
     * survives none of the ordinary things a person does to a file.
     *
     * Best-effort by design. If it cannot be written the crop still works and re-cropping falls back
     * to the crop itself, so nothing here is worth interrupting the user for.
     *
     * Public, with `cropSourceOf`, so the round trip they make between them can be run
     * without standing up a window: what goes in one has to come out of the other, and everything
     * else about FR-032 rests on that.
     *
     * @param crop the crop that was just written
     * @param source the picture it was cut from
     */
    public void rememberCropSource(File crop, File source)
    {
        rememberCropSource(crop, source, null);
    }

    /**
     * The same, also recording WHERE in that picture the crop was taken from (OB-125).
     *
     * A second line, so that a note written before this version - which is every note FR-032 wrote -
     * still reads correctly as a bare path, and so that a note written here read by anything older is
     * a path with a line after it that nothing looks at.
     *
     * @param crop the crop that was just written
     * @param source the picture it was cut from
     * @param view the view the user settled on, or null to record only the source
     */
    public void rememberCropSource(File crop, File source, double[] view)
    {
        final String body = source.getAbsolutePath()
            + (LocIconCropDialog.CropPanel.viewIsUsable(view)
                ? "\n" + CROP_VIEW_PREFIX + view[0] + "," + view[1] + "," + view[2] + ","
                    + view[3] + "," + view[4]
                : "");

        try
        {
            Util.writeAtomically(new File(crop.getAbsolutePath() + CROP_SOURCE_SUFFIX),
                out -> out.write(body.getBytes(java.nio.charset.StandardCharsets.UTF_8)));
        }
        catch (IOException | RuntimeException e)
        {
            // Untidy, not broken.  Re-cropping will use the crop itself.
        }
    }

    /**
     * The view a crop was taken at, when its note records one (OB-125).
     *
     * Answers null for everything unreadable - no note, no view line, the wrong number of values,
     * something that is not a number - because there is a perfectly good fallback in the covering
     * centre crop and nothing here is worth interrupting the user for.
     *
     * @param url the icon currently set on the locomotive
     * @return five numbers as the crop panel writes them, or null
     */
    public double[] cropViewOf(String url)
    {
        String line = cropNoteLine(url, CROP_VIEW_PREFIX);

        if (line == null) return null;

        String[] parts = line.split(",");

        if (parts.length != 5) return null;

        double[] view = new double[5];

        try
        {
            for (int i = 0; i < 5; i++) view[i] = Double.parseDouble(parts[i].trim());
        }
        catch (NumberFormatException notANumber)
        {
            return null;
        }

        return LocIconCropDialog.CropPanel.viewIsUsable(view) ? view : null;
    }

    /**
     * A line of a crop's note that begins with a given prefix, with the prefix taken off.
     *
     * @param url the icon currently set on the locomotive
     * @param prefix what the line starts with
     * @return the rest of that line, or null when there is no note or no such line
     */
    private String cropNoteLine(String url, String prefix)
    {
        if (!Util.isLocIconFile(url)) return null;

        File crop = fileOf(url);

        if (crop == null) return null;

        File note = new File(crop.getAbsolutePath() + CROP_SOURCE_SUFFIX);

        if (!note.exists()) return null;

        try
        {
            for (String line : new String(java.nio.file.Files.readAllBytes(note.toPath()),
                java.nio.charset.StandardCharsets.UTF_8).split("\n"))
            {
                if (line.trim().startsWith(prefix)) return line.trim().substring(prefix.length());
            }
        }
        catch (IOException | RuntimeException unreadable)
        {
            return null;
        }

        return null;
    }

    /**
     * The picture a crop was cut from, if it is still there.
     *
     * @param url the icon currently set on the locomotive
     * @return the original file, or null when there is no note or the file it names has gone
     */
    public File cropSourceOf(String url)
    {
        File note = cropSourceNoteOf(url);

        // The photograph may have been moved, renamed or deleted since - it is the user's file in the
        // user's folder, and nothing here has any claim on it.
        return note != null && note.isFile() ? note : null;
    }

    /**
     * What a crop's note SAYS, whether or not the file it names is there right now.
     *
     * The distinction is the whole of a defect a reviewer found in the first version of this (C5), and
     * it is a data-loss one.  `cropSourceOf` answered null for both "there is no note" and "the note
     * names a photograph I cannot see at the moment", and re-crop treated the two the same: it fell
     * back to cropping the crop, wrote a NEW note naming that crop, and then deleted the old crop and
     * the old note with it.
     *
     * So one re-crop attempted while an external drive was unplugged, or while a OneDrive folder had
     * not finished coming online - which is exactly where this user keeps his pictures - would throw
     * away the only record of where the photograph was, permanently, and leave behind a note pointing
     * at a file it had just deleted.  The icon would never be pannable again.
     *
     * Carrying the old note forward costs nothing and loses nothing: at worst it names a file that
     * never comes back, which is the state the crop was already in.
     *
     * @param url the icon currently set on the locomotive
     * @return the file the note names, existing or not, or null when there is no note to read
     */
    private File cropSourceNoteOf(String url)
    {
        if (!Util.isLocIconFile(url)) return null;

        File crop = fileOf(url);

        if (crop == null) return null;

        File note = new File(crop.getAbsolutePath() + CROP_SOURCE_SUFFIX);

        if (!note.exists()) return null;

        try
        {
            // THE FIRST LINE. A note may now carry a view on a second one (OB-125), and trimming the
            // whole file and calling it a path would hand back both lines as a filename.
            String body = new String(java.nio.file.Files.readAllBytes(note.toPath()),
                java.nio.charset.StandardCharsets.UTF_8);

            String path = body.split("\n")[0].trim();

            return path.isEmpty() ? null : new File(path);
        }
        catch (IOException | RuntimeException e)
        {
            return null;
        }
    }

    /**
     * Crops the icon a locomotive already has, without asking for the file again (FR-032).
     *
     * Adam: "once a custom icon is set, make it possible to crop/pan without first reselecting the
     * source."
     *
     * Works from the original photograph when the crop remembers one, and from the crop itself when it
     * does not - which is the honest fallback rather than a refusal, since tightening a crop is still
     * a useful thing to be able to do.
     *
     * Everything after the dialog is what `setLocIcon` does with a freshly chosen file, and for the
     * same reasons: read the superseded URL BEFORE assigning so a failure in between cannot leave the
     * locomotive pointing at a deleted file, and only ever delete files inside our own folder.
     *
     * @param l the locomotive whose icon is being re-cropped
     * @param parent the component the dialog should centre on
     */
    public void recropLocIcon(Locomotive l, java.awt.Component parent)
    {
        javax.swing.SwingUtilities.invokeLater(() ->
        {
            if (l == null || l.getLocalImageURL() == null) return;

            File source = cropSourceOf(l.getLocalImageURL());

            boolean fromOriginal = source != null;

            // What the note SAID, kept even when the file it names is not there today (C5).  Cropping
            // the crop must not be allowed to forget where the photograph was: the drive comes back,
            // and the icon should still be pannable when it does.
            File remembered = fromOriginal ? null : cropSourceNoteOf(l.getLocalImageURL());

            if (source == null) source = fileOf(l.getLocalImageURL());

            if (source == null || !source.isFile())
            {
                this.model.logf("ui.errorFailedToLoadImage", String.valueOf(l.getLocalImageURL()));

                return;
            }

            // Two slots, the same as the other call site.
            //
            // This passed one to a method that writes slot 1, and was saved only by that method
            // guarding with `cancelled.length > 1` - which silences the mismatch instead of catching
            // it, and leaves the next reader of `cancelled[1]` here with an index out of bounds.
            boolean[] cancelled = {false, false};

            // ONLY when working from the photograph the view was measured over (OB-125).
            //
            // The fallback crops the crop itself, where these coordinates describe somewhere else
            // entirely - the picture underneath them is a different picture.
            String cropped = cropLocIcon(parent, l, source, cancelled,
                fromOriginal ? cropViewOf(l.getLocalImageURL()) : null);

            if (cancelled[0] || cropped == null) return;

            String superseded = l.getLocalImageURL();

            l.setLocalImageURL(cropped);

            // The old note wins over the one just written, which names the crop this was cut from
            // rather than the photograph behind it (C5).
            //
            // No view goes with it. This branch cropped the CROP, so the view describes a point in
            // that crop, while the note names the photograph behind it - storing one against the
            // other would open the next re-crop of the original at coordinates measured on something
            // else (OB-125).
            if (remembered != null)
            {
                File fresh = fileOf(cropped);

                if (fresh != null) rememberCropSource(fresh, remembered);
            }

            if (!cropped.equals(superseded) && Util.isLocIconFile(superseded))
            {
                deleteLocIconFile(superseded);
            }

            // Told, because the difference matters and is invisible: re-cropping a crop cannot pan
            // back out to anything the previous crop threw away.
            // The fallback message does not claim to know WHY there was no original, because there
            // are two reasons and it cannot tell them apart from here: the note named a file that is
            // not there today, or there was never a note - which is every crop made before FR-032.
            // It said "could not be found" for both (validator).
            this.model.logf(fromOriginal ? "loc.ui.infoRecroppedFromOriginal"
                : "loc.ui.infoRecroppedFromCrop", l.getName());

            this.repaintLoc(true, null);
            this.repaintMappings(Collections.singletonList(l), true);
            this.selector.refreshLocSelectorList();
        });
    }

    /**
     * A way in for the test, which cannot reach the private one - the tests live in their own
     * packages, so package-visible is not enough.
     *
     * @param url the URL of the file to remove
     */
    public void deleteLocIcon(String url)
    {
        deleteLocIconFile(url);
    }

    /**
     * Removes a cropped icon file that nothing points at any more.
     *
     * Only ever called for a URL {@link Util#isLocIconFile} has already vouched for, so this cannot
     * reach the user's own pictures.  Failure is ignored on purpose: a stale file in our own folder
     * is untidy, and telling the user about it in the middle of setting an icon that worked would be
     * worse than the untidiness.
     *
     * @param url the URL of the file to remove
     */
    private void deleteLocIconFile(String url)
    {
        try
        {
            File file = new File(new java.net.URI(url));

            // The note about where it came from goes with it (FR-032).  Left behind it would be a file
            // in our own folder that nothing points at and nothing would ever remove.
            new File(file.getAbsolutePath() + CROP_SOURCE_SUFFIX).delete();

            file.delete();
        }
        catch (URISyntaxException | RuntimeException e)
        {
            // Nothing to do and nothing worth saying.  RuntimeException covers the
            // IllegalArgumentException a URL that is not a file URL produces.
        }
    }
    
    /**
     * Returns a file chooser for autonomy files
     * @param type
     * @param extension
     * @return 
     */
    public JFileChooser getFileChooser(int type, String extension)
    {
        JFileChooser fc = new JFileChooser(
            prefs.get(LAST_USED_FOLDER, new File(".").getAbsolutePath())
        );
        
        if ("json".equals(extension))
        {
            FileFilter filter = new FileNameExtensionFilter(I18n.t("ui.jsonFile"), "json");
            fc.setFileFilter(filter);
        }
        else if ("csv".equals(extension))
        {
            FileFilter filter = new FileNameExtensionFilter(I18n.t("ui.csvFile"), "csv");
            fc.setFileFilter(filter);
        }
        else if ("txt".equals(extension))
        {
            FileFilter filter = new FileNameExtensionFilter(I18n.t("ui.textFile"), "txt");
            fc.setFileFilter(filter);
        }
        
        return fc;        
    }
    
    private boolean isAutoLayoutRunning()
    {
        if (this.model.getAutoLayout().isRunning())
        {
            JOptionPane.showMessageDialog(
                this,
                I18n.t("autolayout.ui.errorUnableToChangeSettingsWhileTrainsRunning")
            );
            loadAutoLayoutSettings();
            return true;
        }
        
        return false;
    }
    
    /**
     * Loads all current settings into the UI
     */
    private void loadAutoLayoutSettings()
    {
        this.minDelay.setValue(this.model.getAutoLayout().getMinDelay());
        this.maxDelay.setValue(this.model.getAutoLayout().getMaxDelay());
        this.defaultLocSpeed.setValue(this.model.getAutoLayout().getDefaultLocSpeed());
        this.preArrivalSpeedReduction.setValue(Double.valueOf(this.model.getAutoLayout().getPreArrivalSpeedReduction() * 100).intValue());
        this.maxLocInactiveSeconds.setValue(Double.valueOf(this.model.getAutoLayout().getMaxLocInactiveSeconds() / 60).intValue());
        this.maxActiveTrains.setValue(this.model.getAutoLayout().getMaxActiveTrains());
        this.simulate.setSelected(this.model.getAutoLayout().isSimulate());
        this.atomicRoutes.setSelected(this.model.getAutoLayout().isAtomicRoutes());
        this.turnOffFunctionsOnArrival.setSelected(this.model.getAutoLayout().isTurnOffFunctionsOnArrival());
        this.turnOnFunctionsOnDeparture.setSelected(this.model.getAutoLayout().isTurnOnFunctionsOnDeparture());
        this.maximumLatency.setValue(this.model.getAutoLayout().getMaxLatency());

        // THE ROUTING RULE, PULLED FROM THE LAYOUT LIKE EVERY OTHER SETTING HERE (MT-226).
        //
        // This is the whole of the "when switching from one config to the other, the option stays put"
        // half. A menu read the layout when it happened to be opened; this runs when a configuration
        // is loaded, so the control cannot show one configuration's rule while another is running.
        if (algorithmType != null)
        {
            migrateStoredPathPreference(this.model.getAutoLayout());

            // THE SAME RESTORE THE REFUSAL USES (RC-B11).
            //
            // This had its own copy of the loop and relied on the listener returning early when
            // nothing had changed, to stop it writing the setup back on every load.  That was true and
            // it was the same rule in two places.  The helper holds the guard instead, so the listener
            // does not run here at all - the same outcome by a rule that cannot drift.
            restoreRoutingLogicSelection();
        }        
    }
    
    
    
        
    /**
     * Updates the visibility of certain points and edges
     */
    synchronized public void updateVisiblePoints()
    {
        if (!this.model.hasAutoLayout()) return;

        // The station labels on the track diagram, which is all this does now.
        //
        // It used to style the graph's nodes and edges as well, and to write the labels only when
        // there was no graph window - so on the diagram path the labels were the whole job and on the
        // graph path they were an afterthought.  The graph is gone; the labels are what was worth
        // keeping.
        for (Point p : this.model.getAutoLayout().getPoints())
        {
            this.updateStationLabels(p);
        }

    }
    
        
    
        
    /**
     * Repaints the timetable once a route completes
     */
    // Deliberately not synchronized.  It was, and a caller waiting up to a path configuration for the
    // Layout monitor then held the UI-class monitor for that whole wait - so any click entering another
    // synchronized UI method queued behind it.  The method has nothing left to guard: its only state,
    // lastTimetableState, is read and written solely inside the invokeLater below, which the EDT
    // already serialises, and the snapshot is a local.
    /**
     * What to call a Point in a list a person reads: the station, not the copy of it.
     *
     * OB-102, Adam: "timetable stations show (northbound) and (southbound) etc."
     *
     * A square where trains may turn round is emitted as several Points, one per side a train can
     * arrive by, and they are named "Platform 3 (northbound)" and so on so that a running log can say
     * which way round a train is. That distinction is machinery. In the timetable it is noise: the
     * reader wants to know the train went from Platform 3 to the yard, and every row carrying a
     * compass bearing makes the column wider and the list harder to scan for the one thing it is for.
     *
     * The suffix is not thrown away anywhere else - the editor, the logs and the path descriptions all
     * still carry it, because that is where knowing which copy matters.
     *
     * Off the FIELD, never getAutonomySession(): this runs from repaintTimetable, which deliberately
     * works off the event thread, and that getter is a lazy builder that parses every page, can write
     * to disk and can raise a dialog (SV-B2). With no session - the JSON path - the emitted name is
     * the only name there is, and it is returned unchanged.
     *
     * @param point a Point of the running configuration, or null
     * @return the station's own name
     */
    private String stationLabel(org.traincontrol.automation.Point point)
    {
        if (point == null) return "";

        org.traincontrol.automationui.AutonomySession session = this.autonomySession;

        if (session == null) return point.getName();

        String base = session.baseNameOf(point.getName());

        return base == null ? point.getName() : base;
    }

    /**
     * Gives the timetable its columns, whether or not there is anything to put in them.
     *
     * Adam: "the timetable entry has default table heading when blank.  make sure these are always
     * set."  The form designer starts every JTable off with four columns called "Title 1" through
     * "Title 4" and four blank rows, and these headings used to be installed only from
     * repaintTimetable - so until an autonomy configuration existed and something had happened to it,
     * the Timetable tab showed the designer's placeholder.  On a fresh installation that is the whole
     * time the operator is setting autonomy up, which is when they are most likely to look at it.
     *
     * Called from the constructor as well, which is why it is separate: repaintTimetable's first act
     * is to ask the running Layout for a snapshot, and at construction there is no Layout to ask.
     * Nothing here needs one.
     *
     * Idempotent, on the column count, because both callers may run in either order.
     */
    private void prepareTimetableColumns()
    {
        if (this.timetable.getColumnCount() == 5) return;

        String col[] = {
            I18n.t("timetable.ui.columnIndex"),
            I18n.t("timetable.ui.columnLocomotive"),
            I18n.t("timetable.ui.columnStart"),
            I18n.t("timetable.ui.columnDestination"),
            I18n.t("timetable.ui.columnTime")
        };

        DefaultTableModel tableModel = new DefaultTableModel(col, 0)
        {
            // Disable editing
            @Override
            public boolean isCellEditable(int row, int column)
            {
                return false;
            }
        };

        this.timetable.setModel(tableModel);

        TableRowSorter<TableModel> sorter = new TableRowSorter<>(this.timetable.getModel());
        sorter.setSortable(0, false);
        sorter.setSortable(1, false);
        sorter.setSortable(2, false);
        sorter.setSortable(3, false);
        sorter.setSortable(4, false);
        this.timetable.setRowSorter(sorter);
    }

    /**
     * What the timetable table would SHOW, as one string (MT-149).
     *
     * The redraw is skipped when this has not changed, and it has to be built from the text rather
     * than from the objects: a locomotive hashes by identity, so renaming one changes every row and no
     * hash. Everything the table draws is in here - the order, the locomotive, the two stations and
     * whether the entry has run - and nothing else is, so a repaint is asked for exactly when one is
     * needed.
     *
     * @param timeTable the snapshot about to be drawn
     * @return a key that changes when the drawing would
     */
    private String timetableSignature(List<TimetablePath> timeTable)
    {
        StringBuilder out = new StringBuilder();

        for (TimetablePath path : timeTable)
        {
            out.append(path.getLoc() == null ? "" : path.getLoc().getName()).append('\u0001')
                .append(stationLabel(path.getStart())).append('\u0001')
                .append(stationLabel(path.getEnd())).append('\u0001')
                .append(path.isExecuted()).append('\u0001')
                .append(path.getExecutionTime()).append('\u0001')
                .append(path.getSecondsToNext()).append('\u0002');
        }

        return out.toString();
    }

    private void repaintTimetable()
    {
        // The snapshot must not be taken on the EDT.
        //
        // getTimetableSnapshot holds the Layout monitor, and configureAndLockPath holds that same
        // monitor across its per-command sleeps - half a second to two seconds on an ordinary path,
        // deliberately, because locking a path has to be atomic.  This method runs at every path start
        // and end, so with two or more trains one locomotive is regularly mid-configuration when
        // another’s callback lands here: taken inside the invokeLater, the whole UI froze for the
        // length of someone else’s switch-throwing, over and over.
        //
        // The callback thread pays that wait instead, which is where contention for this monitor is
        // already the design - it holds activeLocomotives at that point, and activeLocomotives ->
        // Layout is the order the completion block already establishes.  Idle callers take it
        // uncontended and hand the EDT a finished copy.
        // The UI callers were left alone on the argument that their busy guard means the monitor is
        // free by the time they run.  That argument is wrong: configureAndLockPath runs *before* the
        // locomotive is put into activeLocomotives, and a hand-launched path never sets running - so
        // for the whole configuration window isRunning(), and with it isAutonomyBusy(), answers false.
        // Three of those callers hold a modal dialog open between the check and the snapshot, so the
        // window is as wide as the operator leaves it.
        //
        // Bouncing off the EDT costs one short-lived thread on a user action and asks nothing of the
        // callers, which still marshal their own work through the invokeLater below.
        if (javax.swing.SwingUtilities.isEventDispatchThread())
        {
            new Thread(() -> this.repaintTimetable()).start();
            return;
        }

        final List<TimetablePath> timeTable = this.model.getAutoLayout().getTimetableSnapshot();

        javax.swing.SwingUtilities.invokeLater(() ->
        {
            prepareTimetableColumns();

            // Update the data
            this.timetableCapture.setSelected(this.model.getAutoLayout().isTimetableCapture());
            
            // Do nothing if what the table SHOWS has not changed (MT-149).
            //
            // This used to compare `timeTable.hashCode()`, and a locomotive hashes by IDENTITY -
            // deliberately, so that renaming one cannot move it out of the consists and run lists that
            // hold it.  TimetablePath's hash is built from that, so a rename changes the name in every
            // row and changes no hash at all.  Measured: the same -1733089858 before and after, with
            // the entry correctly reading the new name underneath.
            //
            // So the redraw was discarded and the table went on showing a locomotive that no longer
            // exists under that name, until something else happened to the timetable.  Adam: "the
            // timetable is not updated".
            //
            // Keyed on the text of the rows instead, which is the only thing that can answer "does
            // this need redrawing".  It costs one string per repaint of a list that is tens of entries
            // long and is built anyway.
            String showing = timetableSignature(timeTable);

            if (showing.equals(lastTimetableState)) return;

            lastTimetableState = showing;
            
            DefaultTableModel tableModel = (DefaultTableModel) this.timetable.getModel();
            tableModel.setRowCount(0);
                        
            for (TimetablePath path : timeTable)
            {
                Object[] data = {tableModel.getRowCount() + 1, path.getLoc().getName(),
                stationLabel(path.getStart()), stationLabel(path.getEnd()),
                path.isExecuted() ? Conversion.convertSecondsToDatetime(path.getExecutionTime()) : "Pending Start +" + (path.getSecondsToNext() / 1000) + "s"};

                tableModel.addRow(data);
            }
        });
    }
    
    synchronized public void repaintAutoLocList(boolean external)
    {
        if (this.model.hasAutoLayout() && this.model.getAutoLayout().isValid())
        {
            // Called from another UI component - an arrival, a departure, a placement.
            if (external)
            {
                if (this.model.getAutoLayout().getPoints().isEmpty()) return;

                // THROTTLED, not suppressed.
                //
                // This used to return outright while autonomy was running with anything active - so
                // every arrival during a run was dropped, the panels sat frozen for the whole session,
                // and the display only caught up when the last train stopped and the list emptied.  A
                // run is precisely when somebody is watching these panels.
                //
                // What made suppression look necessary was cost, and that is now paid elsewhere: the
                // Lite refresh does its searching off the event thread and marshals only the drawing
                // back.  What remains is coalescing, which is what the flag and the pause below are
                // for - a burst of arrivals collapses into one repaint rather than one each.
                //
                // A flag rather than a list of Futures.  The list was scanned for "any not done", so a
                // task that never completed suppressed every later refresh for the rest of the session
                // - a latch with no way back, which is the shape of "after a few start/stops nothing
                // refreshes at all".  This one is cleared in a finally, so a refresh that throws cannot
                // take the display with it.
                if (!this.autoRefreshInFlight.compareAndSet(false, true)) return;

                try
                {
                this.AutonomyRenderer.submit(() ->
                {
                    try
                    {
                        try
                        {
                            Thread.sleep(REPAINT_ROUTE_INTERVAL);
                        }
                        catch (InterruptedException ex)
                        {
                            Thread.currentThread().interrupt();
                        }

                        this.repaintAutoLocListLite();
                    }
                    finally
                    {
                        this.autoRefreshInFlight.set(false);
                    }
                });
                }
                catch (Exception e)
                {
                    // Submitting can be refused - the pool is shut down when the window closes - and
                    // the flag is set by then.  Clearing it here keeps the latch from coming back at
                    // one remove: a single rejected submit would otherwise suppress every refresh for
                    // the rest of the session, which is the exact failure the flag replaced.
                    this.autoRefreshInFlight.set(false);
                }
            }
            else
            {
                this.repaintAutoLocListFull();
            }
        }
    }
    
    /**
     * Repaints the auto locomotive list paths only
     */
    synchronized private void repaintAutoLocListLite()
    { 
        javax.swing.SwingUtilities.invokeLater(() ->
        {
            // Arrivals enter here - the callback fires on a locomotive thread, which is why this sits
            // inside the invokeLater rather than above it.  Full does NOT funnel through here, so it
            // carries the same line: an earlier version of this fix claimed it did, and moved the
            // staleness from arrivals onto placements instead of removing it.
            this.refreshReturnHomeButton();

            // Same reasoning, for "Activate Routes" (UXR-B3): isAutonomyBusy can turn false on its
            // own the moment the last active locomotive arrives, with neither the checkbox nor the
            // list having been touched, and this is the refresh that already runs at that moment.
            refreshActivateRoutesControls();

            // Which panels there are is read HERE, on the EDT, because the component list belongs to
            // Swing.  What goes in them is worked out somewhere else.
            final java.util.List<AutoLocomotiveStatus> panels = new java.util.ArrayList<>();

            for (Object o : this.autoLocPanel.getComponents())
            {
                panels.add((AutoLocomotiveStatus) o);
            }

            // The search off the EDT, the drawing back on it.
            //
            // updateState sets text, swaps list models and toggles visibility, so it has to be on the
            // EDT - a raw thread used to run the whole thing off it, which was the fault that got the
            // thread removed.  But the search inside it is synchronized on the Layout and walks the
            // whole graph, once per panel, on every arrival and departure: on the EDT that stalls the
            // interface, and lets it block on a monitor a driving thread holds.
            //
            // So both halves go where they belong rather than both going to one place.
            AutonomyRenderer.submit(() ->
            {
                final java.util.Map<AutoLocomotiveStatus, java.util.List<java.util.List<Edge>>> found =
                    new java.util.LinkedHashMap<>();

                for (AutoLocomotiveStatus panel : panels)
                {
                    try
                    {
                        found.put(panel, panel.findPaths());
                    }
                    catch (RuntimeException e)
                    {
                        // The layout is being replaced underneath us; the next refresh catches up
                        this.model.log(e);

                        return;
                    }
                }

                javax.swing.SwingUtilities.invokeLater(() ->
                {
                    for (AutoLocomotiveStatus panel : panels)
                    {
                        // null is "did not search", not "searched and found nothing".  findPaths bails
                        // while the layout is running, and by the time THIS runnable reaches the event
                        // thread the run can have ended - so the panel would take the standing-by
                        // branch, be handed a null answer stamped as authoritative, and print "no
                        // available paths" with nothing left to correct it.  That is what a panel stuck
                        // on that line at the end of a run was.
                        java.util.List<java.util.List<Edge>> answer = found.get(panel);

                        panel.updateState(null, answer, answer != null);
                    }
                });
            });
        });
    }
    
    /**
     * Fully repaints the auto locomotive list based on auto layout state
     */
    synchronized private void repaintAutoLocListFull()
    { 
        javax.swing.SwingUtilities.invokeLater(() ->
        {
            // The other terminal path.  Every placement and removal call site reaches the button
            // through here, not through Lite.
            this.refreshReturnHomeButton();

            // Display locomotive status and possible paths
            this.autoLocPanel.removeAll();

            // Number of columns in the grid
            int gridCols = 3;

            autoLocPanel.setLayout(new java.awt.GridLayout(
                (int) Math.ceil((double) this.model.getAutoLayout().getLocomotivesToRun().size() / gridCols), 
                gridCols, // cols
                5, // padding
                5)
            );
            
            // Sort alphabetically, with parked locomotives last
            List<Locomotive> locs = new LinkedList<>(this.model.getAutoLayout().getLocomotivesToRun());
            
            locs.sort((Locomotive l1, Locomotive l2) ->
            {
                Point loc1Point = this.model.getAutoLayout().getLocomotiveLocation(l1);
                Point loc2Point = this.model.getAutoLayout().getLocomotiveLocation(l2);
                
                if (loc1Point != null && loc2Point != null)
                {
                    if (loc1Point.isActive() && !loc2Point.isActive()) return -1;
                    if (!loc1Point.isActive() && loc2Point.isActive()) return 1;
                }
                else if (loc1Point == null)
                {
                    return 1;
                }
                else if (loc2Point == null)
                {
                    return -1;
                }            
                
                return l1.getName().compareTo(l2.getName());
            });
            
            // The panels are built here, on the event thread, where Swing components belong - but the
            // search each one used to do in its own constructor is not done here any more.
            //
            // AutoLocomotiveStatus's constructor calls updateState, which calls getPossiblePaths: a
            // method synchronized on the Layout that walks the whole graph, once per locomotive.  On
            // the EDT that stalls the interface and lets it block on a monitor a driving thread holds.
            // The Lite path was moved off the event thread for exactly this reason and its twin here
            // was left behind, reached from every manual placement and removal.
            //
            // Built empty and filled in afterwards: the panels appear at once, and each takes its
            // routes when the worker has them.
            final java.util.List<AutoLocomotiveStatus> panels = new java.util.LinkedList<>();

            for (Locomotive loc : locs)
            {
                AutoLocomotiveStatus panel = new AutoLocomotiveStatus(loc, this, true);

                panels.add(panel);

                this.autoLocPanel.add(panel);
            }

            AutonomyRenderer.submit(() ->
            {
                final java.util.Map<AutoLocomotiveStatus, java.util.List<java.util.List<Edge>>> found
                    = new java.util.LinkedHashMap<>();

                for (AutoLocomotiveStatus panel : panels)
                {
                    try
                    {
                        found.put(panel, panel.findPaths());
                    }
                    catch (Exception e)
                    {
                        // Still entered, as "did not search".  A panel left out of the map was never
                        // updated at all, so one locomotive whose search threw sat blank until
                        // something else repainted the whole list.
                        found.put(panel, null);

                        if (this.model.isDebug()) this.model.log(e);
                    }
                }

                javax.swing.SwingUtilities.invokeLater(() ->
                {
                    for (java.util.Map.Entry<AutoLocomotiveStatus,
                        java.util.List<java.util.List<Edge>>> entry : found.entrySet())
                    {
                        entry.getKey().updateState(entry.getKey().getLocomotive(),
                            entry.getValue(), entry.getValue() != null);
                    }
                });
            });
            
            // Speed up scrolling
            autoLocScroll.getVerticalScrollBar().setUnitIncrement(16);

            // Sometimes the list doesn't repaint until you click on it.  Alernative might be to do this before rendering the graph.
            this.autoLocPanel.repaint();
            this.locCommandPanels.repaint();
        });
    }

    @Override
    public boolean confirmRouteConflictMidway(Route r, String accessory, String reason)
    {
        // The same dialog the two doors ask BEFORE a route starts, asked again when the railway
        // changed under it (Adam, 2026-08-25: "ask me, at the two human doors").
        //
        // One wording for both moments on purpose. From where the operator stands they are the same
        // question - autonomy has taken this accessory, do you want it set anyway - and the fact that
        // one is asked before the first command and the other between two of them is an implementation
        // detail he has no reason to learn.
        //
        // Reached only from a route a person started; the s88 trigger door has nobody to ask, so it
        // sets none of its accessories and runs the rest (VD9-C18 - this said "stops without
        // asking"),
        // because there is nobody there. Called on the route's own thread, and the dialog marshals
        // itself onto the event thread, so this blocks that route and nothing else.
        if (!(r instanceof org.traincontrol.marklin.MarklinRoute)) return false;

        // known != null, so there is always a conflict to ask about and NOTHING_TO_CONFIRM cannot
        // come back here.
        return askAboutRouteConflict((org.traincontrol.marklin.MarklinRoute) r, this,
            new String[] {accessory, reason}) == RouteConflict.OVERRIDE;
    }

    @Override
    public void emergencyStopTriggered(Route r)
    {
        javax.swing.SwingUtilities.invokeLater(() ->
        {
            JOptionPane.showMessageDialog(
                this,
                I18n.f(
                    "route.ui.infoPowerAutomaticallyTurnedOffBecauseRouteTriggered",
                    r.getName()
                )
            );
        });
    }

    @Override
    public void showAutonomyAlert(String message)
    {
        // Non-blocking so the autonomy thread that raised the alert is not held up
        javax.swing.SwingUtilities.invokeLater(() ->
        {
            JOptionPane.showMessageDialog(
                this,
                message,
                I18n.t("autolayout.ui.pathConfigErrorTitle"),
                JOptionPane.WARNING_MESSAGE
            );
        });
    }
         

    /**
     * The routes whose play button is currently a spinner (FR-043).
     *
     * A name rather than a Route, because the table is rebuilt from the model constantly and the object
     * in a cell is not the object the run was started against - `refreshRouteList` maps names to Routes
     * afresh every time, so holding the object would leave a spinner attached to a discarded copy.
     *
     * Concurrent: written from the route threads and read by the renderer on the event thread.
     */
    private final java.util.Set<String> routesExecuting =
        java.util.concurrent.ConcurrentHashMap.newKeySet();

    /**
     * When each running route was marked, so the debug line can say how long it lasted.
     *
     * The number that settles whether a state nobody saw was never set or merely brief.
     */
    private final java.util.Map<String, Long> startedRunningAt =
        new java.util.concurrent.ConcurrentHashMap<>();

    /**
     * The play button: the glyph's size, and the strip of cell that presses it.
     *
     * Adam asked for a mark "about the same height as the text", which is Segoe UI 14 here - so the
     * GLYPH stays that size. What changed is that the target is not the glyph.
     *
     * The first version made the two the same thing: thirteen pixels square, eight in from the right
     * edge, in a row thirty tall. That is about one and a half percent of the cell, hard against its
     * border, and Adam's verdict was "play buttons not clickable". The geometry was right - built
     * headless, a click at the drawn centre lands in the hit box in every cell - it was simply too
     * small to hit, and missing it opened the right-click menu.
     *
     * So the pressable part is a strip the full height of the row, with the glyph drawn in the middle
     * of it. The strip is also what keeps the text off the icon (OB-146): the renderer reserves it as
     * a border inset, so a long route name runs out of room before the glyph rather than over it.
     */
    private static final int ROUTE_PLAY_SIZE = 13;
    private static final int ROUTE_PLAY_STRIP = 30;

    /**
     * Marks a route as running and starts the animation.
     *
     * @param route the route's name
     */
    private void routeStarted(String route)
    {
        if (route == null) return;

        routesExecuting.add(route);

        startedRunningAt.put(route, System.currentTimeMillis());

        // SAID OUT LOUD, in debug, because "nothing happens visually" cannot be told apart from "it
        // happened and was too quick to see" without a measurement - and I have guessed wrong about
        // which of those it is once already.
        if (this.model != null && this.model.isDebug())
        {
            this.model.log("Route " + route + " marked as running");
        }

        // A REBUILD RATHER THAN A REPAINT (MT-217, third report).
        //
        // Adam: "the routes fire, but the play buttons next to the route name just don't change at
        // all." The route running is the fact that settles it - executeRoute marks the route before it
        // starts the thread, so the mark IS set and the repaint is simply not landing on the cell.
        //
        // refreshRouteList replaces the table's model, which cannot fail to redraw every cell. It is
        // what the rest of this window uses whenever a route changes and it already runs at the end of
        // every route execution, so this is the mechanism that is known to work here rather than a
        // second one that ought to.
        javax.swing.SwingUtilities.invokeLater(() -> refreshRouteList());
    }

    /**
     * The route has finished, so its button comes back.
     *
     * @param route the route's name
     */
    private void routeFinished(String route)
    {
        if (route == null) return;

        // LATER OF THE TWO: when the route ended, or when the grey has been on screen long enough.
        //
        // Adam's one-second experiment settled what three rounds of reading could not. The drawing was
        // never the problem - the CLEAR was. A route finishes fast enough that the button was put back
        // before the grey had been on screen long enough to see, so the state was correct, brief, and
        // invisible.
        //
        // A floor rather than a fixed hold - though on today's code the two are the same thing, and
        // the sentence that used to stand here claimed otherwise (`V34-C4`).
        //
        // The argument for the floor was that a fixed hold would put the button back while the route
        // was still running.  It cannot: `execRoute` starts a thread and returns, so `routeFinished`
        // is reached milliseconds after `routeStarted` and `showFor` is always about the whole minimum.
        // The floor is what makes the grey VISIBLE, which is the fault Adam reported; it is not what
        // keeps it honest about a slow route, and nothing here is.
        //
        // Worth keeping the shape: if the execution ever becomes synchronous, the floor is already
        // right and a fixed hold would not be.
        Long since = startedRunningAt.get(route);

        long showFor = since == null ? 0
            : ROUTE_MINIMUM_VISIBLE_MS - (System.currentTimeMillis() - since);

        if (showFor > 0)
        {
            javax.swing.SwingUtilities.invokeLater(() ->
            {
                javax.swing.Timer rest = new javax.swing.Timer((int) showFor,
                    e -> clearRunningRoute(route));

                rest.setRepeats(false);
                rest.start();
            });

            return;
        }

        clearRunningRoute(route);
    }

    /**
     * How long a pressed play button stays grey at the very least, in milliseconds.
     *
     * Long enough to register as a state rather than a flicker; short enough that firing several
     * routes one after another does not feel gated by an animation.
     */
    private static final int ROUTE_MINIMUM_VISIBLE_MS = 600;

    /**
     * Puts the button back, now.
     *
     * @param route the route's name
     */
    private void clearRunningRoute(String route)
    {
        routesExecuting.remove(route);

        Long began = startedRunningAt.remove(route);

        if (this.model != null && this.model.isDebug())
        {
            this.model.log("Route " + route + " no longer running"
                + (began == null ? "" : " after " + (System.currentTimeMillis() - began) + "ms"));
        }

        // The same rebuild that put the grey there takes it away again.
        javax.swing.SwingUtilities.invokeLater(() -> refreshRouteList());
    }

    /**
     * Puts every play button back, whatever it was doing.
     *
     * Adam: "any database sync, import, or completed route edits should reset all spinners in this
     * view."
     *
     * CALLED FROM THOSE THREE, and not from `refreshRouteList`, which is where I first put it. All
     * three do end there, which is what made it look like the one place worth wiring - but so does a
     * route FINISHING, so the first route to complete wiped the spinner off every other route still
     * running. On a table where firing several in a row is the ordinary thing to do, that is the
     * feature failing exactly when it is being used.
     *
     * Three callers of one method, rather than one rule with an accidental fourth.
     *
     * A spinner is a claim that something is running. After a sync or an import there is no longer any
     * way to know whether it still is, and a spinner that cannot be trusted is worse than none: it
     * makes a route look busy for ever, and the button that would run it is not there to press.
     */
    public void resetRouteSpinners()
    {
        routesExecuting.clear();
        startedRunningAt.clear();
    }

    /**
     * Whether a click landed on a cell's play button rather than on the cell.
     *
     * The button is painted by the renderer at the right-hand end of the cell, so its box is worked out
     * the same way here - from the cell's own rectangle - rather than from anything the renderer
     * remembers. A renderer is one component reused for every cell; asking it where it last drew would
     * be asking about whichever cell was painted most recently.
     *
     * @param evt the click
     * @return true if the pointer is over the button of a cell that has one
     */
    private boolean isOverTheRoutePlayButton(java.awt.event.MouseEvent evt)
    {
        int row = RouteList.rowAtPoint(evt.getPoint());
        int column = RouteList.columnAtPoint(evt.getPoint());

        if (row < 0 || column < 0) return false;

        // An empty cell has no button: the last row is padded out to three columns with nulls.
        if (RouteList.getValueAt(row, column) == null) return false;

        java.awt.Rectangle cell = RouteList.getCellRect(row, column, true);

        java.awt.Rectangle button = routePlayButtonBox(cell);

        return button.contains(evt.getPoint());
    }

    /**
     * Where the play button sits inside a cell.
     *
     * One answer, used by the renderer that draws it and by the click that has to hit it. Two
     * calculations of the same rectangle is how a control comes to be drawn in one place and pressed in
     * another.
     *
     * @param cell the cell's rectangle
     * @return the button's rectangle
     */
    public static java.awt.Rectangle routePlayButtonBox(java.awt.Rectangle cell)
    {
        return new java.awt.Rectangle(cell.x + cell.width - ROUTE_PLAY_STRIP, cell.y,
            ROUTE_PLAY_STRIP, cell.height);
    }

    /**
     * Where the triangle is drawn inside that strip.
     *
     * Separate from the strip because they are different sizes on purpose: the mark is the size Adam
     * asked for and the target is the size a target has to be. Keeping them as one number is what made
     * the button unhittable.
     *
     * @param strip the pressable strip
     * @return the glyph's box, centred in it
     */
    public static java.awt.Rectangle routePlayGlyphBox(java.awt.Rectangle strip)
    {
        return new java.awt.Rectangle(
            strip.x + (strip.width - ROUTE_PLAY_SIZE) / 2,
            strip.y + (strip.height - ROUTE_PLAY_SIZE) / 2,
            ROUTE_PLAY_SIZE, ROUTE_PLAY_SIZE);
    }

    /**
     * The route Find Route last landed on, drawn highlighted until something else happens (FR-044).
     *
     * A name rather than a cell, because the table is rebuilt constantly and re-sorted by preference -
     * a row and column would point at whatever moved into that square afterwards. It is also why the
     * highlight survives a refresh: the route is still that route wherever it has been put.
     */
    private String foundRoute;

    /**
     * The wash behind a route Find Route has just landed on.
     *
     * A pale yellow rather than the selection blue: this is the application pointing at something, not
     * the user having selected it, and a cell that looks selected invites the next click to be about
     * that selection.
     */
    private static final Color FOUND_BACKGROUND = new Color(255, 246, 190);

    /**
     * The wash behind a route that is running.
     *
     * Grey rather than a colour, because this is the cell saying "not just now" - the same thing the
     * greyed triangle says, at a size that is noticed rather than looked for.
     */
    private static final Color RUNNING_BACKGROUND = new Color(226, 226, 226);

    /**
     * Adds Find Route to the routes menu.
     *
     * Hand-mounted, like the layout menu's headings and for the same reason: anything declared inside
     * a GEN-BEGIN block is deleted the next time the form is regenerated. Guarded so that being called
     * twice cannot mount it twice.
     */
    private void mountFindRoute()
    {
        if (routesMenu == null || findRouteMenuItem != null) return;

        findRouteMenuItem = new javax.swing.JMenuItem(I18n.t("route.ui.menuFindRoute"));

        findRouteMenuItem.addActionListener(e -> findRoute());

        // At the top, above Export and Import.  Those two are about the route list as a file; this is
        // about finding your way around it, which is what somebody opening this menu while looking at
        // the routes is far more likely to want.
        routesMenu.add(findRouteMenuItem, 0);
        routesMenu.add(new javax.swing.JPopupMenu.Separator(), 1);
    }

    private javax.swing.JMenuItem findRouteMenuItem;

    /**
     * Asks for a route by name and goes to it (FR-044).
     *
     * Adam: "'Find Route' popup that asks the user for the route name.  system jumps to the route page
     * and highlights the matched cell (scrolling to it if needed), otherwise shows a notice that it
     * doesn't exist."
     *
     * Matched case-insensitively, and on a unique CONTAINS when nothing matches exactly - somebody who
     * types "yard" and has one route with that in its name meant that route, and refusing them on
     * exactness would be pedantry. Ambiguity is not resolved by guessing: two matches is treated as no
     * match, because landing on the wrong one silently is worse than being told to be specific.
     */
    private void findRoute()
    {
        String asked = JOptionPane.showInputDialog(this, I18n.t("route.ui.promptFindRoute"),
            I18n.t("route.ui.menuFindRoute"), JOptionPane.PLAIN_MESSAGE);

        // Cancel returns null, which is not the same as an empty search - and neither is worth a
        // "no such route" complaint about a question nobody answered.
        if (asked == null || asked.trim().isEmpty()) return;

        String wanted = asked.trim();

        List<String> matches = routesMatchingIn(this.model.getRouteList(), wanted);

        if (matches.isEmpty())
        {
            JOptionPane.showMessageDialog(this, I18n.f("route.ui.errorNoSuchRoute", wanted));

            return;
        }

        String found = matches.get(0);

        // MORE THAN ONE: ASK, rather than guess or refuse (MT-218).
        //
        // The key this asks with was already in all eight bundles and used by nothing - written for
        // this and never wired up.
        if (matches.size() > 1)
        {
            found = (String) JOptionPane.showInputDialog(this,
                I18n.t("route.ui.promptWhichRoute"), I18n.t("route.ui.menuFindRoute"),
                JOptionPane.PLAIN_MESSAGE, null, matches.toArray(), matches.get(0));

            // Cancelled, which is not the same as choosing the first one.
            if (found == null) return;
        }

        showRouteInTheList(found);
    }

    /**
     * The route this text names, or null when it names none or more than one.
     *
     * @param wanted what was typed
     * @return the route's real name
     */
    private String routeNamed(String wanted)
    {
        return routeNamedIn(this.model.getRouteList(), wanted);
    }

    /**
     * The same question, asked of a plain list so it can be exercised without a railway.
     *
     * EXACT MATCHES FIRST, and that order is the whole of it rather than a tidy-up. A layout with
     * "Yard" and "Yard Bypass" on it makes "Yard" both an exact name and a substring of another - and
     * a rule that looked for substrings first would call that ambiguous and refuse to find a route
     * whose name the user typed in full.
     *
     * @param names every route there is
     * @param wanted what was typed, already trimmed
     * @return the one route this names, or null for none and for more than one
     */
    public static String routeNamedIn(List<String> names, String wanted)
    {
        List<String> matches = routesMatchingIn(names, wanted);

        return matches.size() == 1 ? matches.get(0) : null;
    }

    /**
     * Every route this text could mean, best first.
     *
     * An exact name is not one candidate among several - it is the answer, so it comes back alone.
     * Anything else comes back as the list of routes whose names contain the text, in the order the
     * model lists them.
     *
     * Ambiguity is handled by ASKING rather than by guessing or refusing (MT-218). Adam: "let's
     * support partial matching if there is no exact match as entered." Partial matching was already
     * there; what it did when a fragment fitted several routes was give up, on the reasoning that
     * landing silently on one of them is worse than saying no. That reasoning is right and refusing
     * was still the wrong conclusion - the third option is to put the list in front of the user.
     *
     * @param names every route there is
     * @param wanted what was typed, already trimmed
     * @return the candidates, empty when nothing matches, exactly one when the answer is certain
     */
    public static List<String> routesMatchingIn(List<String> names, String wanted)
    {
        List<String> found = new ArrayList<>();

        if (names == null || wanted == null || wanted.trim().isEmpty()) return found;

        // EXACT FIRST, and alone.  A layout with "Yard" and "Yard Bypass" makes "Yard" both a name and
        // part of another - and offering a choice there would be asking somebody to confirm a name
        // they had already typed in full, which is the most definite thing they can do.
        for (String name : names)
        {
            if (name.equalsIgnoreCase(wanted))
            {
                found.add(name);

                return found;
            }
        }

        for (String name : names)
        {
            if (name.toLowerCase().contains(wanted.toLowerCase())) found.add(name);
        }

        return found;
    }

    /**
     * Brings the route list up, scrolls to a route and highlights it.
     *
     * @param name the route's name, as the model spells it
     */
    private void showRouteInTheList(String name)
    {
        foundRoute = name;

        // The routes tab, found by identity rather than counted to - the same reasoning as the sidebar
        // icons, where getComponentAt(4) was right only by luck of the designer's ordering.
        int routesAt = this.KeyboardTab.indexOfComponent(this.RoutePanel);

        if (routesAt >= 0) this.KeyboardTab.setSelectedIndex(routesAt);

        for (int row = 0; row < this.RouteList.getRowCount(); row++)
        {
            for (int column = 0; column < this.RouteList.getColumnCount(); column++)
            {
                Object at = this.RouteList.getValueAt(row, column);

                if (!(at instanceof Route) || !name.equals(((Route) at).getName())) continue;

                this.RouteList.scrollRectToVisible(this.RouteList.getCellRect(row, column, true));

                this.RouteList.repaint();

                return;
            }
        }

        // In the model but not in the table, which means the table is mid-rebuild or the route is
        // filtered out of it. The highlight is already set, so the next repaint shows it wherever it
        // lands; there is simply nothing to scroll to yet.
        this.RouteList.repaint();
    }

    /**
     * Forgets the found route, so the highlight does not outlive the question it answered.
     */
    private void clearFoundRoute()
    {
        if (foundRoute == null) return;

        foundRoute = null;

        this.RouteList.repaint();
    }

    public class CustomTableRenderer extends DefaultTableCellRenderer
    {
        // Support hover events
        private int hoveredRow = -1;
        private int hoveredColumn = -1;
        
        public void setHoveredCell(int row, int column)
        {
            hoveredRow = row;
            hoveredColumn = column;
        }
        
        public void resetHoveredCell()
        {
            hoveredRow = -1;
            hoveredColumn = -1;
        }

        /**
         * Which route this stamp is currently set up to draw, or null for an empty cell.
         */
        private String paintingRoute;

        /**
         * Draws the cell, then the play button on the right of it (FR-043).
         *
         * Adam: "there is a green play button (execute) icon on the right side of each cell.  make it
         * be about the same height as the text... when the execute button is pressed, convert it to a
         * spinner animation that reverts back to the button once the route execution is finished."
         *
         * Painted rather than added, because a table cell is not a live component - it is this one
         * renderer, configured and stamped once per cell. That is also why the spinner needs the timer
         * in the window: nothing here animates on its own.
         *
         * A TURNING ARC rather than the hourglass the rest of the application waits behind. The
         * hourglass is the mark for a modal wait with nothing else to do; this is a small busy mark
         * inside a list that stays usable, and Adam asked for "a spinner animation" in those words.
         * The 60ms frame is shared with LoadingSpinner even so, because two marks turning at visibly
         * different rates read as two different kinds of waiting.
         */
        @Override
        protected void paintComponent(java.awt.Graphics g)
        {
            super.paintComponent(g);

            if (paintingRoute == null) return;

            java.awt.Graphics2D g2 = (java.awt.Graphics2D) g.create();

            try
            {
                g2.setRenderingHint(java.awt.RenderingHints.KEY_ANTIALIASING,
                    java.awt.RenderingHints.VALUE_ANTIALIAS_ON);

                // The renderer is stamped at the cell's origin, so the button's box is worked out
                // against a rectangle of this component's own size - the same arithmetic the click
                // uses, through the same method, so the two cannot drift.
                java.awt.Rectangle box = routePlayGlyphBox(routePlayButtonBox(
                    new java.awt.Rectangle(0, 0, getWidth(), getHeight())));

                // GREY WHILE IT RUNS, GREEN WHEN IT DOES NOT (MT-217).
                //
                // Adam: "there is no animation / change in state while it is running.  It should gray
                // out and then become reenabled once the route finishes."
                //
                // This was a turning arc, and the timer that drove it is gone with it. A disabled
                // button needs two repaints in its whole life rather than sixteen a second, and it is
                // a state that is either true or false rather than one you have to catch happening -
                // which matters for a route that finishes in under a second.
                boolean running = routesExecuting.contains(paintingRoute);

                g2.setColor(running ? new java.awt.Color(170, 170, 170) : new java.awt.Color(0, 150, 0));

                java.awt.Polygon play = new java.awt.Polygon();

                play.addPoint(box.x, box.y);
                play.addPoint(box.x + box.width, box.y + box.height / 2);
                play.addPoint(box.x, box.y + box.height);

                g2.fillPolygon(play);
            }
            finally
            {
                g2.dispose();
            }
        }
        
        @Override
        public Component getTableCellRendererComponent(JTable table, Object value,
                boolean isSelected, boolean hasFocus, int row, int column)
        {
            Component c = super.getTableCellRendererComponent(table, value, isSelected,
                    hasFocus, row, column);

            // Hover effect
            JLabel j = (JLabel) c;
            
            // FOUND FIRST, then hover, then plain (FR-044).
            //
            // A found route outranks the pointer resting on something: Find Route exists to show you
            // where a route is, and the answer disappearing because the mouse happens to be elsewhere
            // would be the feature undoing itself. It is cleared by the next find, by a click, or by
            // anything that rebuilds the table.
            if (value != null && routesExecuting.contains(((Route) value).getName()))
            {
                // THE WHOLE CELL, not just the triangle (MT-217, third attempt).
                //
                // Adam has reported twice that nothing changes when he presses a play button. The
                // triangle greying is a thirteen-pixel shape changing hue at the end of a cell nobody
                // is looking at; a cell that washes grey is seen without being looked for. If this is
                // still not visible then the mark is not being set at all, which is what the debug
                // lines in routeStarted and routeFinished are there to say.
                j.setBackground(RUNNING_BACKGROUND);
            }
            else if (value != null && ((Route) value).getName().equals(foundRoute))
            {
                j.setBackground(FOUND_BACKGROUND);
            }
            else if (row == hoveredRow && column == hoveredColumn && value != null)
            {
                j.setBackground(new Color(240,240,240));
            }
            else
            {
                j.setBackground(Color.WHITE);
            }
          
            // Determine the border to set
            int top = 0;
            int left = 0;
            int bottom = 1;
            
            // This is overkill, but will ensure no double border at the bottom of the frame
            if (row == table.getRowCount() - 1)
            {
                // Check if the table is inside a JScrollPane with a visible vertical scrollbar
                JScrollBar verticalBar = routeScrollPane.getVerticalScrollBar();
                if (verticalBar != null && verticalBar.isVisible()) {
                    bottom = 0;
                }
            }
     
            int right = 1;

            j.setFont(new Font("Segoe UI", Font.PLAIN, 14));

            // THE STRIP IS RESERVED FROM THE TEXT (OB-146).
            //
            // Adam: "play icons in routes can be on top of text - make the text (route titles) wrap
            // before hitting them."  A long name ran the full width of the cell and the glyph was
            // painted on top of whatever was there.
            //
            // Reserved as an inset rather than policed by the drawing, so the label lays its own text
            // out inside a narrower box and ellipsises when it runs out - the text cannot reach the
            // icon because the space is not the text's to use.
            //
            // NOT wrapped, which is the letter of what he asked. A JLabel wraps only as HTML, and the
            // rows here are a fixed thirty pixels: two lines of Segoe UI 14 need about thirty-eight,
            // so wrapping would hide the second line rather than show it. Wrapping wants a taller row,
            // which changes the look of the whole table - his call, and asked in MT-217.
            j.setBorder(BorderFactory.createCompoundBorder(
                BorderFactory.createMatteBorder(top, left, bottom, right, new Color(208,208,208)),
                BorderFactory.createEmptyBorder(0, 0, 0, ROUTE_PLAY_STRIP)));
            // End hover effect
            
            // Remembered for paintComponent, which is called immediately after this and has no other
            // way to know which cell it is drawing: one renderer serves every cell in the table.
            this.paintingRoute = value == null ? null : ((Route) value).getName();

            if (value != null)
            {
                String name = ((Route) value).getName();
                
                // Show route ID if sorting by ID
                if (prefs.getBoolean(ROUTE_SORT_PREF, false))
                {
                    setText(name);
                }
                else
                {
                    setText(model.getRouteId(name) + ". " + name);
                }
                
                // Differentiate central station routes
                if (model.getRoute(name).isLocked())
                {
                    setText(getText() + " *");
                    // setToolTipText("Route from Central Station.");
                }
                else
                {
                    // setToolTipText("");
                }
                
                // Add padding due to hover effect
                setText(" " + getText());
                
                if (model.getRoute(name).isEnabled() && model.getRoute(name).hasS88())
                {
                    // set to red bold font
                    c.setForeground(Color.RED);
                    c.setFont(new Font("Segoe UI", Font.BOLD, 14));
                } 
                else 
                {
                    // stay at default
                    c.setForeground(Color.BLACK);
                    c.setFont(new Font("Segoe UI", Font.PLAIN, 14));
                }
            }
  
            return c;
        }
    }
    
